@article{Zhang_Zhang_Chan_Zhang_U_2024, title={A Computation-Aware Shape Loss Function for Point Cloud Completion}, volume={38}, url={https://ojs.aaai.org/index.php/AAAI/article/view/28558}, DOI={10.1609/aaai.v38i7.28558}, abstractNote={Learning-based point cloud completion tasks have shown potential in various critical tasks, such as object detection, assignment, and registration. However, accurately and efficiently quantifying the shape error between the predicted point clouds generated by networks and the ground truth remains challenging. While EMD-based loss functions excel in shape detail and perceived density distribution, their approach can only yield results with significant discrepancies from the actual EMD within a tolerable training time.
To address these challenges, we first propose the initial price based on the auction algorithm, reducing the number of iterations required for the algorithm while ensuring the correctness of the assignment results. We then introduce an algorithm to compute the initial price through a successive shortest path and the Euclidean information between its nodes. Finally, we adopt a series of optimization strategies to speed up the algorithm and offer an EMD approximation scheme for point cloud problems that balances time loss and computational accuracy based on point cloud data characteristics.
Our experimental results confirm that our algorithm achieves the smallest gap with the real EMD within an acceptable time range and yields the best results in end-to-end training.}, number={7}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Zhang, Shunran and Zhang, Xiubo and Chan, Tsz Nam and Zhang, Shenghui and U, Leong Hou}, year={2024}, month={Mar.}, pages={7287-7295} }

@article{Liu_Xiao_Zhou_2024, title={A Fast Exact Solver with Theoretical Analysis for the Maximum Edge-Weighted Clique Problem}, volume={38}, url={https://ojs.aaai.org/index.php/AAAI/article/view/30065}, DOI={10.1609/aaai.v38i18.30065}, abstractNote={The maximum vertex-weighted clique problem (MVWCP) and the maximum edge-weighted clique problem (MEWCP) are two natural extensions of the fundamental maximum clique problem. In this paper, we systematically study MEWCP and make the following major contributions:
(1) We show that MEWCP is NP-hard even when the minimum degree of the graph is n-2, in contrast to MVWCP which is polynomial-time solvable when the minimum degree of the graph is at least n-3. This result distinguishes the complexity of the two problems for the first time.
(2) To address MEWCP, we develop an efficient branch-and-bound algorithm called MEWCat with both practical and theoretical performance guarantees. In practice, MEWCat utilizes a new upper bound tighter than existing ones, which allows for more efficient pruning of branches. In theory, we prove a running-time bound of O*(1.4423^n) for MEWCat, which breaks the trivial bound of O*(2^n) in the research line of practical exact MEWCP solvers for the first time.
(3) Empirically, we evaluate the performance of MEWCat on various benchmark instances. The experiments demonstrate that MEWCat outperforms state-of-the-art exact solvers significantly. For instance, on 16 DIMACS graphs that the state-of-the-art solver BBEWC fails to solve within 7200 seconds, MEWCat solves all of them with an average time of less than 1000 seconds. On real-world graphs, MEWCat achieves an average speedup of over 36x.}, number={18}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Liu, Lu and Xiao, Mingyu and Zhou, Yi}, year={2024}, month={Mar.}, pages={20768-20776} }

@article{Gilo_Markovitch_2024, title={A General Search-Based Framework for Generating Textual Counterfactual Explanations}, volume={38}, url={https://ojs.aaai.org/index.php/AAAI/article/view/29764}, DOI={10.1609/aaai.v38i16.29764}, abstractNote={One of the prominent methods for explaining the decision of a machine-learning classifier is by a counterfactual example.
Most current algorithms for generating such examples in the textual domain are based on generative language models. Generative models, however, are trained to minimize a specific loss function in order to fulfill certain requirements for the generated texts. Any change in the requirements may necessitate costly retraining, thus potentially limiting their applicability.
In this paper, we present a general search-based framework for generating counterfactual explanations in the textual domain. Our framework is model-agnostic, domain-agnostic, anytime, and does not require retraining in order to adapt to changes in the user requirements. We model the task as a search problem in a space where the initial state is the classified text, and the goal state is a text in a given target class. Our framework includes domain-independent modification operators, but can also exploit domain-specific knowledge through specialized operators. The search algorithm attempts to find a text from the target class with minimal user-specified distance from the original classified object.}, number={16}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Gilo, Daniel and Markovitch, Shaul}, year={2024}, month={Mar.}, pages={18073-18081} }

@article{Wang_Xing_Jiang_Chen_Mei_Zuo_Dai_Wang_Liu_2024, title={A Multimodal, Multi-Task Adapting Framework for Video Action Recognition}, volume={38}, url={https://ojs.aaai.org/index.php/AAAI/article/view/28361}, DOI={10.1609/aaai.v38i6.28361}, abstractNote={Recently, the rise of large-scale vision-language pretrained models like CLIP, coupled with the technology of Parameter-Efficient FineTuning (PEFT), has captured substantial attraction in video action recognition. Nevertheless, prevailing approaches tend to prioritize strong supervised performance at the expense of compromising the models’ generalization capabilities during transfer. In this paper, we introduce a novel Multimodal, Multi-task CLIP adapting framework named M2-CLIP to address these challenges, preserving both high supervised performance and robust transferability.
Firstly, to enhance the individual modality architectures, we introduce multimodal adapters to both the visual and text branches. Specifically, we design a novel visual TED-Adapter, that performs global Temporal Enhancement and local temporal Difference modeling to improve the temporal representation capabilities of the visual encoder. Moreover, we adopt text encoder adapters to strengthen the learning of semantic label information.
Secondly, we design a multi-task decoder with a rich set of supervisory signals, including the original contrastive learning head, a cross-modal classification head, a cross-modal masked language modeling head, and a visual classification head. This multi-task decoder adeptly satisfies the need for strong supervised performance within a multimodal framework.
Experimental results validate the efficacy of our approach, demonstrating exceptional performance in supervised learning while maintaining strong generalization in zero-shot scenarios.}, number={6}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Wang, Mengmeng and Xing, Jiazheng and Jiang, Boyuan and Chen, Jun and Mei, Jianbiao and Zuo, Xingxing and Dai, Guang and Wang, Jingdong and Liu, Yong}, year={2024}, month={Mar.}, pages={5517-5525} }

@article{Yue_Luo_Xu_2024, title={A Plug-and-Play Quaternion Message-Passing Module for Molecular Conformation Representation}, volume={38}, url={https://ojs.aaai.org/index.php/AAAI/article/view/29602}, DOI={10.1609/aaai.v38i15.29602}, abstractNote={Graph neural networks have been widely used to represent 3D molecules, which capture molecular attributes and geometric information through various message-passing mechanisms.
This study proposes a novel quaternion message-passing (QMP) module that can be plugged into many existing 3D molecular representation models and enhance their power for distinguishing molecular conformations.
In particular, our QMP module represents the 3D rotations between one chemical bond and its neighbor bonds as a quaternion sequence. Then, it aggregates the rotations by the chained Hamilton product of the quaternions. The real part of the output quaternion is invariant to the global 3D rotations of molecules but sensitive to the local torsions caused by twisting bonds, providing discriminative information for training molecular conformation representation models. In theory, we prove that considering these features enables invariant GNNs to distinguish the conformations caused by bond torsions. We encapsulate the QMP module with acceleration, so combining existing models with the QMP requires merely one-line code and little computational cost. Experiments on various molecular datasets show that plugging our QMP module into existing invariant GNNs leads to consistent and significant improvements in molecular conformation representation and downstream tasks.}, number={15}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Yue, Angxiao and Luo, Dixin and Xu, Hongteng}, year={2024}, month={Mar.}, pages={16633-16641} }

@article{Xing_Venkatraman_Le_Lee_2024, title={ALISON: Fast and Effective Stylometric Authorship Obfuscation}, volume={38}, url={https://ojs.aaai.org/index.php/AAAI/article/view/29901}, DOI={10.1609/aaai.v38i17.29901}, abstractNote={Authorship Attribution (AA) and Authorship Obfuscation (AO) are two competing tasks of increasing importance in privacy research. Modern AA leverages an author’s consistent writing style to match a text to its author using an AA classifier. AO is the corresponding adversarial task, aiming to modify a text in such a way that its semantics are preserved, yet an AA model cannot correctly infer its authorship. To address privacy concerns raised by state-of-the-art (SOTA) AA methods,
new AO methods have been proposed but remain largely impractical to use due to their prohibitively slow training and obfuscation speed, often taking hours.
To this challenge, we propose a practical AO method, ALISON, that (1) dramatically reduces training/obfuscation time, demonstrating more than 10x faster obfuscation than SOTA AO methods, (2) achieves better obfuscation success through attacking three transformer-based AA methods on two benchmark datasets, typically performing 15% better than competing methods, (3) does not require direct signals from a target AA classifier during obfuscation, and (4) utilizes unique stylometric features, allowing sound model interpretation for explainable obfuscation. We also demonstrate that ALISON can effectively prevent four SOTA AA methods from accurately determining the authorship of ChatGPT-generated texts, all while minimally changing the original text semantics. To ensure the reproducibility of our findings, our code and data are available at: https://github.com/EricX003/ALISON.}, number={17}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Xing, Eric and Venkatraman, Saranya and Le, Thai and Lee, Dongwon}, year={2024}, month={Mar.}, pages={19315-19322} }

@article{Han_Peng_Dong_Ren_Shen_Xu_2024, title={AMD: Autoregressive Motion Diffusion}, volume={38}, url={https://ojs.aaai.org/index.php/AAAI/article/view/27973}, DOI={10.1609/aaai.v38i3.27973}, abstractNote={Human motion generation aims to produce plausible human motion sequences according to various conditional inputs, such as text or audio. Despite the feasibility of existing methods in generating motion based on short prompts and simple motion patterns, they encounter difficulties when dealing with long prompts or complex motions.
The challenges are two-fold: 1) the scarcity of human motion-captured data for long prompts and complex motions. 2) the high diversity of human motions in the temporal domain and the substantial divergence of distributions from conditional modalities, leading to a many-to-many mapping problem when generating motion with complex and long texts. In this work, we address these gaps by 1) elaborating the first dataset pairing long textual descriptions and 3D complex motions (HumanLong3D), and 2) proposing an autoregressive motion diffusion model (AMD). Specifically, AMD integrates the text prompt at the current timestep with the text prompt and action sequences at the previous timestep as conditional information to predict the current action sequences in an iterative manner.
Furthermore, we present its generalization for X-to-Motion with “No Modality Left Behind”, enabling for the first time the generation of high-definition and high-fidelity human motions based on user-defined modality input.}, number={3}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Han, Bo and Peng, Hao and Dong, Minjing and Ren, Yi and Shen, Yixuan and Xu, Chang}, year={2024}, month={Mar.}, pages={2022-2030} }

@article{Mor_Belinkov_Kimelfeld_2024, title={Accelerating the Global Aggregation of Local Explanations}, volume={38}, url={https://ojs.aaai.org/index.php/AAAI/article/view/29845}, DOI={10.1609/aaai.v38i17.29845}, abstractNote={Local explanation methods highlight the input tokens that have a considerable impact on the outcome of classifying the document at hand. For example, the Anchor algorithm applies a statistical analysis of the sensitivity of the classifier to changes in the token. Aggregating local explanations over a dataset provides a global explanation of the model.
Such aggregation aims to detect words with the most impact, giving valuable insights about the model, like what it has learned in training and which adversarial examples expose its weaknesses.
However, standard aggregation methods bear a high computational cost:
a naive implementation applies a costly algorithm to each token of each document, and hence, it is infeasible for a simple user running in the scope of a short analysis session. We devise techniques for accelerating the global aggregation of the Anchor algorithm. Specifically, our goal is to compute a set of top-k words with the highest global impact according to different aggregation functions. Some of our techniques are lossless and some are lossy.
We show that for a very mild loss of quality, we are able to accelerate the computation by up to 30 times, reducing the computation from hours to minutes. We also devise and study a probabilistic model that accounts for noise in the Anchor algorithm and diminishes the bias toward words that are frequent yet low in impact.}, number={17}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Mor, Alon and Belinkov, Yonatan and Kimelfeld, Benny}, year={2024}, month={Mar.}, pages={18807-18814} }

@article{Lee_Kim_Lee_Kwak_2024, title={Any-Way Meta Learning}, volume={38}, url={https://ojs.aaai.org/index.php/AAAI/article/view/29242}, DOI={10.1609/aaai.v38i12.29242}, abstractNote={Although meta-learning seems promising performance in the realm of rapid adaptability, it is constrained by fixed cardinality. When faced with tasks of varying cardinalities that were unseen during training, the model lacks its ability. In this paper, we address and resolve this challenge by harnessing `label equivalence’ emerged from stochastic numeric label assignments during episodic task sampling. Questioning what defines ``true&quot; meta-learning, we introduce the ``any-way&quot; learning paradigm, an innovative model training approach that liberates model from
fixed cardinality constraints. Surprisingly, this model not only matches but often outperforms traditional fixed-way models in terms of performance, convergence speed, and stability. This disrupts established notions
about domain generalization. Furthermore, we argue that the inherent label equivalence naturally lacks semantic information. To bridge this semantic information gap arising from label equivalence, we further propose a mechanism for infusing semantic class information into the model. This would enhance the model’s comprehension and functionality. Experiments conducted on renowned architectures like MAML and ProtoNet affirm the effectiveness of our method.}, number={12}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Lee, JunHoo and Kim, Yearim and Lee, Hyunho and Kwak, Nojun}, year={2024}, month={Mar.}, pages={13400-13408} }

@article{Cho_Shin_Oh_2024, title={Approximate Distance Oracle for Fault-Tolerant Geometric Spanners}, volume={38}, url={https://ojs.aaai.org/index.php/AAAI/article/view/29987}, DOI={10.1609/aaai.v38i18.29987}, abstractNote={In this paper, we present approximate distance and shortest-path oracles for fault-tolerant Euclidean spanners motivated by the routing problem in real-world road networks.
A fault-tolerant Euclidean spanner for a set of points in Euclidean space is a graph
in which, despite the deletion of small number of any points, the distance between any two points in the damaged graph is an approximation of their Euclidean distance. Given a fault-tolerant Euclidean spanner and a small approximation factor, our data structure allows us to compute an approximate distance between two points in the damaged spanner in constant time when a query involves any two points and a small set of failed points. Additionally, by incorporating additional data structures, we can return a path itself in time almost linear in the length of the returned path. Both data structures require near-linear space.}, number={18}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Cho, Kyungjin and Shin, Jihun and Oh, Eunjin}, year={2024}, month={Mar.}, pages={20087-20095} }

@article{Curry_Thoma_Chakrabarti_McAleer_Kroer_Sandholm_He_Seuken_2024, title={Automated Design of Affine Maximizer Mechanisms in Dynamic Settings}, volume={38}, url={https://ojs.aaai.org/index.php/AAAI/article/view/28819}, DOI={10.1609/aaai.v38i9.28819}, abstractNote={Dynamic mechanism design is a challenging extension to ordinary mechanism design in which the mechanism designer must make a sequence of decisions over time in the face of possibly untruthful reports of participating agents.
Optimizing dynamic mechanisms for welfare is relatively well understood. However, there has been less work on optimizing for other goals (e.g., revenue), and without restrictive assumptions on valuations, it is remarkably challenging to characterize good mechanisms. Instead, we turn to automated mechanism design to find mechanisms with good performance in specific problem instances.
We extend the class of affine maximizer mechanisms to MDPs where agents may untruthfully report their rewards. This extension results in a challenging bilevel optimization problem in which the upper problem involves choosing optimal mechanism parameters, and the lower problem involves solving the resulting MDP. Our approach can find truthful dynamic mechanisms that achieve strong performance on goals other than welfare, and can be applied to essentially any problem setting---without restrictions on valuations---for which RL can learn optimal policies.}, number={9}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Curry, Michael and Thoma, Vinzenz and Chakrabarti, Darshan and McAleer, Stephen and Kroer, Christian and Sandholm, Tuomas and He, Niao and Seuken, Sven}, year={2024}, month={Mar.}, pages={9626-9635} }

@article{Alvi_French_Keymer_Cardell-Oliver_2024, title={Automated State Estimation for Summarizing the Dynamics of Complex Urban Systems Using Representation Learning}, volume={38}, url={https://ojs.aaai.org/index.php/AAAI/article/view/30344}, DOI={10.1609/aaai.v38i21.30344}, abstractNote={Complex urban systems can be difficult to monitor, diagnose and manage because the complete states of such systems are only partially observable with sensors. State estimation techniques can be used to determine the
underlying dynamic behavior of such complex systems with their highly non-linear processes and external time-variant influences.
States can be estimated by clustering observed sensor readings. However,
clustering performance degrades as the number of sensors and readings (i.e. feature dimension) increases. To address this problem, we propose a framework that learns a feature-centric lower dimensional representation of data for clustering to support analysis of system dynamics. We propose Unsupervised Feature Attention with Compact Representation (UFACR) to rank features contributing to a cluster assignment. These weighted features are then used to learn a reduced-dimension temporal representation of the data with a deep-learning model. The resulting low-dimensional representation can be effectively clustered into states. UFACR is evaluated on real-world and synthetic wastewater treatment plant data sets, and feature ranking outcomes were validated by Wastewater treatment domain experts. Our quantitative and qualitative experimental analyses demonstrate the effectiveness of UFACR for uncovering system dynamics in an automated and unsupervised manner to offer guidance to wastewater engineers to enhance industrial productivity and treatment efficiency.}, number={21}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Alvi, Maira and French, Tim and Keymer, Philip and Cardell-Oliver, Rachel}, year={2024}, month={Mar.}, pages={23020-23026} }

@article{Leo_Gange_Garcia de la Banda_Wallace_2024, title={Automatic Core-Guided Reformulation via Constraint Explanation and Condition Learning}, volume={38}, url={https://ojs.aaai.org/index.php/AAAI/article/view/28645}, DOI={10.1609/aaai.v38i8.28645}, abstractNote={SAT and propagation solvers often underperform for optimisation models whose objective sums many single-variable terms.
MaxSAT solvers avoid this by detecting and exploiting cores: subsets of these terms that cannot collectively take their lower bounds.
Previous work has shown manual analysis of cores can help define model reformulations likely to speed up solving for many model instances.
This paper presents a method to automate this process.
For each selected core the method identifies the instance constraints that caused it;
infers the model constraints and parameters that explain how these instance constraints were formed;
and learns the conditions that made those model constraint instances generate cores, while others did not.
It then uses this information to reformulate the objective.
The empirical evaluation shows this method can produce useful reformulations.
Importantly, the method can be useful in many other situations that require explaining a set of constraints.}, number={8}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Leo, Kevin and Gange, Grame and Garcia de la Banda, Maria and Wallace, Mark}, year={2024}, month={Mar.}, pages={8065-8072} }

@article{Sheng_Zhang_Jiang_Kang_2024, title={BBScore: A Brownian Bridge Based Metric for Assessing Text Coherence}, volume={38}, url={https://ojs.aaai.org/index.php/AAAI/article/view/29414}, DOI={10.1609/aaai.v38i13.29414}, abstractNote={Measuring the coherence of text is a vital aspect of evaluating the quality of written content. Recent advancements in neural coherence modeling have demonstrated their efficacy in capturing entity coreference and discourse relations, thereby enhancing coherence evaluation. However, many existing methods heavily depend on static embeddings or focus narrowly on nearby context, constraining their capacity to measure the overarching coherence of long texts.
In this paper, we posit that coherent texts inherently manifest a sequential and cohesive interplay among sentences, effectively conveying the central theme, purpose, or standpoint. To explore this abstract relationship, we introduce the &quot;BB Score,&quot; a novel reference-free metric grounded in Brownian bridge theory for assessing text coherence. Our findings showcase that when synergized with a simple additional classification component, this metric attains a performance level comparable to state-of-the-art techniques on standard artificial discrimination tasks.
We also establish in downstream tasks that this metric effectively differentiates between human-written documents and text generated by large language models within specific domains. Furthermore, we illustrate the efficacy of this approach in detecting written styles attributed to various large language models, underscoring its potential for generalizability. In summary, we present a novel Brownian bridge coherence metric capable of measuring both local and global text coherence, while circumventing the need for end-to-end model training. This flexibility allows for its application in various downstream tasks.}, number={13}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Sheng, Zhecheng and Zhang, Tianhao and Jiang, Chen and Kang, Dongyeop}, year={2024}, month={Mar.}, pages={14937-14945} }

@article{Morishita_Koreeda_Yamaguchi_Morio_Imaichi_Sogawa_2024, title={CHICOT: A Developer-Assistance Toolkit for Code Search with High-Level Contextual Information}, volume={38}, url={https://ojs.aaai.org/index.php/AAAI/article/view/30575}, DOI={10.1609/aaai.v38i21.30575}, abstractNote={We propose a source code search system named CHICOT (Code search with HIgh level COnText) to assist developers in reusing existing code.
While previous studies have examined code search on the basis of code-level, fine-grained specifications such as functionality, logic, or implementation, CHICOT addresses a unique mission: code search with high-level contextual information, such as the purpose or domain of a developer’s project.
It achieves this feature by first extracting the context information from codebases and then considering this context during the search.
It provides a VSCode plugin for daily coding assistance, and the built-in crawler ensures up-to-date code suggestions.
The case study attests to the utility of CHICOT in real-world scenarios.}, number={21}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Morishita, Terufumi and Koreeda, Yuta and Yamaguchi, Atsuki and Morio, Gaku and Imaichi, Osamu and Sogawa, Yasuhiro}, year={2024}, month={Mar.}, pages={23817-23819} }

@article{Vo_Aadil_Chau_Muandet_2024, title={Causal Strategic Learning with Competitive Selection}, volume={38}, url={https://ojs.aaai.org/index.php/AAAI/article/view/29466}, DOI={10.1609/aaai.v38i14.29466}, abstractNote={We study the problem of agent selection in causal strategic learning under multiple decision makers and address two key challenges that come with it. Firstly, while much of prior work focuses on studying a fixed pool of agents that remains static regardless of their evaluations, we consider the impact of selection procedure by which agents are not only evaluated, but also selected.
When each decision maker unilaterally selects agents by maximising their own utility, we show that the optimal selection rule is a trade-off between selecting the best agents and providing incentives to maximise the agents’ improvement. Furthermore, this optimal selection rule relies on incorrect predictions of agents’ outcomes. Hence, we study the conditions under which a decision maker’s optimal selection rule will not lead to deterioration of agents’ outcome nor cause unjust reduction in agents’ selection chance. To that end, we provide an analytical form of the optimal selection rule and a mechanism to retrieve the causal parameters from observational data, under certain assumptions on agents’ behaviour. Secondly, when there are multiple decision makers, the interference between selection rules introduces another source of biases in estimating the underlying causal parameters. To address this problem, we provide a cooperative protocol which all decision makers must collectively adopt to recover the true causal parameters. Lastly, we complement our theoretical results with simulation studies.
Our results highlight not only the importance of causal modeling as a strategy to mitigate the effect of gaming, as suggested by previous work, but also the need of a benevolent regulator to enable it.}, number={14}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Vo, Kiet Q. H. and Aadil, Muneeb and Chau, Siu Lun and Muandet, Krikamol}, year={2024}, month={Mar.}, pages={15411-15419} }

@article{Falque_Audemard_Lecoutre_Mazure_2024, title={Check-In Desk Scheduling Optimisation at CDG International Airport}, volume={38}, url={https://ojs.aaai.org/index.php/AAAI/article/view/30308}, DOI={10.1609/aaai.v38i21.30308}, abstractNote={More than ever, air transport players (i.e., airline and airport companies) in an intensely competitive climate need to benefit from a carefully optimized management of airport resources to improve the quality of service and control the induced costs.
In this paper, we investigate the Airport Check-in Desk Assignment Problem.
We propose a Constraint Programming (CP) model for this problem, and present some promising experimental results from data coming from ADP (Aéroport de Paris).
Our works are deployed in a preprod environment since 1 year.}, number={21}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Falque, Thibault and Audemard, Gilles and Lecoutre, Christophe and Mazure, Bertrand}, year={2024}, month={Mar.}, pages={22743-22751} }

@article{Fan_Wei_Wang_Zhuang_Wang_Zhou_2024, title={Collaborative Tooth Motion Diffusion Model in Digital Orthodontics}, volume={38}, url={https://ojs.aaai.org/index.php/AAAI/article/view/27935}, DOI={10.1609/aaai.v38i2.27935}, abstractNote={Tooth motion generation is an essential task in digital orthodontic treatment for precise and quick dental healthcare, which aims to generate the whole intermediate tooth motion process given the initial pathological and target ideal tooth alignments. Most prior works for multi-agent motion planning problems usually result in complex solutions.
Moreover, the occlusal relationship between upper and lower teeth is often overlooked. In this paper, we propose a collaborative tooth motion diffusion model. The critical insight is to remodel the problem as a diffusion process. In this sense, we model the whole tooth motion distribution with a diffusion model and transform the planning problem into a sampling process from this distribution.
We design a tooth latent representation to provide accurate conditional guides consisting of two key components: the tooth frame represents the position and posture, and the tooth latent shape code represents the geometric morphology. Subsequently, we present a collaborative diffusion model to learn the multi-tooth motion distribution based on inter-tooth and occlusal constraints, which are implemented by graph structure and new loss functions, respectively. Extensive qualitative and quantitative experiments demonstrate the superiority of our framework in the application of orthodontics compared with state-of-the-art methods.}, number={2}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Fan, Yeying and Wei, Guangshun and Wang, Chen and Zhuang, Shaojie and Wang, Wenping and Zhou, Yuanfeng}, year={2024}, month={Mar.}, pages={1679-1687} }

@article{Fang_Ai_Zhan_Liu_Wu_Cao_2024, title={Combining Multiple Supervision for Robust Zero-Shot Dense Retrieval}, volume={38}, url={https://ojs.aaai.org/index.php/AAAI/article/view/29755}, DOI={10.1609/aaai.v38i16.29755}, abstractNote={Recently, dense retrieval (DR) models, which represent queries and documents with fixed-width vectors and retrieve relevant ones via nearest neighbor search, have drawn increasing attention from the IR community. However, previous studies have shown that the effectiveness of DR critically relies on sufficient training signals, which leads to severe performance degradation when applied in out-of-domain scenarios, where large-scale training data are usually unavailable.
To solve this problem, existing studies adopt a data-augmentation-plus-joint-training paradigm to construct weak/pseudo supervisions on the target domain and combine them with the large-scale human annotated data on the source domain to train the DR models. However, they don’t explicitly distinguish the data and the supervision signals in the training process and simply assume that the DR models are mighty enough to capture and memorize different domain knowledge and relevance matching patterns without guidance, which, as shown in this paper, is not true.
Based on this observation, we propose a Robust Multi-Supervision Combining strategy (RMSC) that
decouples the domain and supervision signals by explicitly telling the DR models how the domain data and supervision signals are combined in the training data with specially designed soft tokens. With the extra soft tokens to store the domain-specific and supervision-specific knowledge, RMSC allows the DR models to conduct retrieval based on human-like relevance matching patterns and target-specific language distribution on the target domain without human annotations.
Extensive experiments on zero-shot DR benchmarks show that RMSC significantly improves the ranking performance on the target domain compared to strong DR baselines and domain adaptation methods, while being stable during training and can be combined with query generation or second-stage pre-training.}, number={16}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Fang, Yan and Ai, Qingyao and Zhan, Jingtao and Liu, Yiqun and Wu, Xiaolong and Cao, Zhao}, year={2024}, month={Mar.}, pages={17994-18002} }

@article{Shimizu_Higa_Fujita_Nakadai_2024, title={Coordination of Emergent Demand Changes via Value-Based Negotiation for Supply Chain Management (Student Abstract)}, volume={38}, url={https://ojs.aaai.org/index.php/AAAI/article/view/30510}, DOI={10.1609/aaai.v38i21.30510}, abstractNote={We propose an automated negotiation for a reinforcement learning agent to adapt the agent to unexpected situations such as demand changes in supply chain management (SCM).
Existing studies that consider reinforcement learning and SCM assume a centralized environment where the coordination of chain components is hierarchical rather than through negotiations between agents.
This study focused on a negotiation agent that considered the value function of reinforcement learning for SCM as its utility function in automated negotiation.
We demonstrated that the proposed approach could avoid inventory shortages under increased demand requests from the terminal customer.}, number={21}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Shimizu, Takumu and Higa, Ryota and Fujita, Katsuhide and Nakadai, Shinji}, year={2024}, month={Mar.}, pages={23649-23650} }

@article{Alex_Ahmed_Mustafa_Awais_Jackson_2024, title={DTF-AT: Decoupled Time-Frequency Audio Transformer for Event Classification}, volume={38}, url={https://ojs.aaai.org/index.php/AAAI/article/view/29716}, DOI={10.1609/aaai.v38i16.29716}, abstractNote={Convolutional neural networks (CNNs) and Transformer-based networks have recently enjoyed significant attention for various audio classification and tagging tasks following their wide adoption in the computer vision domain.
Despite the difference in information distribution between audio spectrograms and natural images, there has been limited exploration of effective information retrieval from spectrograms using domain-specific layers tailored for the audio domain. In this paper, we leverage the power of the Multi-Axis Vision Transformer (MaxViT) to create DTF-AT (Decoupled Time-Frequency Audio Transformer) that facilitates interactions across time, frequency, spatial, and channel dimensions.
The proposed DTF-AT architecture is rigorously evaluated across diverse audio and speech classification tasks, consistently establishing new benchmarks for state-of-the-art (SOTA) performance. Notably, on the challenging AudioSet 2M classification task, our approach demonstrates a substantial improvement of 4.4% when the model is trained from scratch and 3.2% when the model is initialised from ImageNet-1K pretrained weights. In addition, we present comprehensive ablation studies to investigate the impact and efficacy of our proposed approach. The codebase and pretrained weights are available on https://github.com/ta012/DTFAT.git}, number={16}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Alex, Tony and Ahmed, Sara and Mustafa, Armin and Awais, Muhammad and Jackson, Philip JB}, year={2024}, month={Mar.}, pages={17647-17655} }

@article{Baldoni_Baroglio_Bucciarelli_Capecchi_Gandolfi_Gena_Ianì_Marengo_Micalizio_Rapp_Ras_2024, title={Does Any AI-Based Activity Contribute to Develop AI Conception? A Case Study with Italian Fifth and Sixth Grade Classes}, volume={38}, url={https://ojs.aaai.org/index.php/AAAI/article/view/30350}, DOI={10.1609/aaai.v38i21.30350}, abstractNote={Artificial Intelligence is undoubtedly becoming pervasive in everyday life of everyone.
In this setting, developing correct AI conception since childhood is not only a need to be addressed in educational curricula, but is also a children right. Accordingly, several initiatives at national and international levels aim at promoting AI
and emerging technology literacy, supported also by a proliferation in the literature of learning courses covering a variety of topics, learning objectives and targeted ages.
Schools are therefore pushed to introduce innovative activities for children in their
curricula. In this paper, we report the results of a case study where we tested the contribution of an AI block-based course in developing computational thinking, and human and AI minds understanding in fifth and sixth grade children.}, number={21}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Baldoni, Matteo and Baroglio, Cristina and Bucciarelli, Monica and Capecchi, Sara and Gandolfi, Elena and Gena, Cristina and Ianì, Francesco and Marengo, Elisa and Micalizio, Roberto and Rapp, Amon and Ras, Ivan Nabil}, year={2024}, month={Mar.}, pages={23060-23068} }

@article{Chen_Wang_Wang_Pan_Shi_Cai_Ren_Zhu_Deng_2024, title={Dynamic Budget Throttling in Repeated Second-Price Auctions}, volume={38}, url={https://ojs.aaai.org/index.php/AAAI/article/view/28816}, DOI={10.1609/aaai.v38i9.28816}, abstractNote={In today’s online advertising markets, a crucial requirement for an advertiser is to control her total expenditure within a time horizon under some budget. Among various budget control methods, throttling has emerged as a popular choice, managing an advertiser’s total expenditure by selecting only a subset of auctions to participate in.
This paper provides a theoretical panorama of a single advertiser’s dynamic budget throttling process in repeated second-price auctions.
We first establish a lower bound on the regret and an upper bound on the asymptotic competitive ratio for any throttling algorithm, respectively, when the advertiser’s values are stochastic and adversarial. Regarding the algorithmic side, we propose the OGD-CB algorithm, which guarantees a near-optimal expected regret with stochastic values. On the other hand, when values are adversarial, we prove that this algorithm also reaches the upper bound on the asymptotic competitive ratio. We further compare throttling with pacing, another widely adopted budget control method, in repeated second-price auctions. In the stochastic case, we demonstrate that pacing is generally superior to throttling for the advertiser, supporting the well-known result that pacing is asymptotically optimal in this scenario. However, in the adversarial case, we give an exciting result indicating that throttling is also an asymptotically optimal dynamic bidding strategy. Our results bridge the gaps in theoretical research of throttling in repeated auctions and comprehensively reveal the ability of this popular budget-smoothing strategy.}, number={9}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Chen, Zhaohua and Wang, Chang and Wang, Qian and Pan, Yuqi and Shi, Zhuming and Cai, Zheng and Ren, Yukun and Zhu, Zhihua and Deng, Xiaotie}, year={2024}, month={Mar.}, pages={9598-9606} }

@article{Zhang_Luo_Liu_Yang_Dong_Gudovskiy_Okuno_Nakata_Keutzer_Du_Zhang_2024, title={Efficient Deweahter Mixture-of-Experts with Uncertainty-Aware Feature-Wise Linear Modulation}, volume={38}, url={https://ojs.aaai.org/index.php/AAAI/article/view/29622}, DOI={10.1609/aaai.v38i15.29622}, abstractNote={The Mixture-of-Experts (MoE) approach has demonstrated outstanding scalability in multi-task learning including low-level upstream tasks such as concurrent removal of multiple adverse weather effects.
However, the conventional MoE architecture with parallel Feed Forward Network (FFN) experts leads to significant parameter and computational overheads that hinder its efficient deployment. In addition, the naive MoE linear router is suboptimal in assigning task-specific features to multiple experts which limits its further scalability.
In this work, we propose an efficient MoE architecture with weight sharing across the experts. Inspired by the idea of linear feature modulation (FM), our architecture implicitly instantiates multiple experts via learnable activation modulations on a single shared expert block.
The proposed Feature Modulated Expert (FME) serves as a building block for the novel Mixture-of-Feature-Modulation-Experts (MoFME) architecture, which can scale up the number of experts with low overhead.
We further propose an Uncertainty-aware Router (UaR) to assign task-specific features to different FM modules with well-calibrated weights. This enables MoFME to effectively learn diverse expert functions for multiple tasks.
The conducted experiments on the multi-deweather task show that our MoFME outperforms the state-of-the-art in the image restoration quality by 0.1-0.2 dB while saving more than 74% of parameters and 20% inference time over the conventional MoE counterpart. Experiments on the downstream segmentation and classification tasks further demonstrate the generalizability of MoFME to real open-world applications.}, number={15}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Zhang, Rongyu and Luo, Yulin and Liu, Jiaming and Yang, Huanrui and Dong, Zhen and Gudovskiy, Denis and Okuno, Tomoyuki and Nakata, Yohei and Keutzer, Kurt and Du, Yuan and Zhang, Shanghang}, year={2024}, month={Mar.}, pages={16812-16820} }

@article{George_Dimitrakakis_2024, title={Eliciting Kemeny Rankings}, volume={38}, url={https://ojs.aaai.org/index.php/AAAI/article/view/29105}, DOI={10.1609/aaai.v38i11.29105}, abstractNote={We formulate the problem of eliciting agents’ preferences with the goal of finding a Kemeny ranking as a Dueling Bandits problem.
Here the bandits’ arms correspond to alternatives that need to be ranked and the feedback corresponds to a pairwise comparison between alternatives by a randomly sampled agent.
We consider both sampling with and without replacement, i.e., the possibility to ask the same agent about some comparison multiple times or not. We find approximation bounds for Kemeny rankings dependant on confidence intervals over estimated winning probabilities of arms. Based on these we state algorithms to find Probably Approximately Correct (PAC) solutions and elaborate on their sample complexity for sampling with or without replacement.
Furthermore, if all agents’ preferences are strict rankings over the alternatives, we provide means to prune confidence intervals and thereby guide a more efficient elicitation. We formulate several adaptive sampling methods that use look-aheads to estimate how much confidence intervals (and thus approximation guarantees) might be tightened. All described methods are compared on synthetic data.}, number={11}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={George, Anne-Marie and Dimitrakakis, Christos}, year={2024}, month={Mar.}, pages={12164-12171} }

@article{Gill_Vakilian_Thrampoulidis_2024, title={Engineering the Neural Collapse Geometry of Supervised-Contrastive Loss (Student Abstract)}, volume={38}, url={https://ojs.aaai.org/index.php/AAAI/article/view/30447}, DOI={10.1609/aaai.v38i21.30447}, abstractNote={Supervised-contrastive loss (SCL) is an alternative to cross-entropy (CE) for classification tasks that makes use of similarities in the embedding space to allow for richer representations. Previous works have used trainable prototypes to help
improve test accuracy of SCL when training under imbalance. In this work, we propose the use of fixed prototypes to help engineering the feature geometry when training with SCL. We gain further insights by considering a limiting scenario
where the number of prototypes far outnumber the original batch size. Through this, we establish a connection to CE loss with a fixed classifier and normalized embeddings. We validate our findings by conducting a series of experiments with deep neural networks on benchmark vision datasets.}, number={21}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Gill, Jaidev and Vakilian, Vala and Thrampoulidis, Christos}, year={2024}, month={Mar.}, pages={23503-23505} }

@article{Fan_Wei_Qu_Lu_Xie_Cheng_Chen_2024, title={Enhancing Low-Resource Relation Representations through Multi-View Decoupling}, volume={38}, url={https://ojs.aaai.org/index.php/AAAI/article/view/29752}, DOI={10.1609/aaai.v38i16.29752}, abstractNote={Recently, prompt-tuning with pre-trained language models (PLMs) has demonstrated the significantly enhancing ability of relation extraction (RE) tasks. However, in low-resource scenarios, where the available training data is scarce, previous prompt-based methods may still perform poorly for prompt-based representation learning due to a superficial understanding of the relation. To this end, we highlight the importance of learning high-quality relation representation in low-resource scenarios for RE, and propose a novel prompt-based relation representation method, named MVRE (Multi-View Relation Extraction), to better leverage the capacity of PLMs to improve the performance of RE within the low-resource prompt-tuning paradigm. Specifically, MVRE decouples each relation into different perspectives to encompass multi-view relation representations for maximizing the likelihood during relation inference.
Furthermore, we also design a Global-Local loss and a Dynamic-Initialization method for better alignment of the multi-view relation-representing virtual words, containing the semantics of relation labels during the optimization learning process and initialization. Extensive experiments on
three benchmark datasets show that our method can achieve
state-of-the-art in low-resource settings.}, number={16}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Fan, Chenghao and Wei, Wei and Qu, Xiaoye and Lu, Zhenyi and Xie, Wenfeng and Cheng, Yu and Chen, Dangyang}, year={2024}, month={Mar.}, pages={17968-17976} }

@article{Tsuchida_Ong_Sejdinovic_2024, title={Exact, Fast and Expressive Poisson Point Processes via Squared Neural Families}, volume={38}, url={https://ojs.aaai.org/index.php/AAAI/article/view/30041}, DOI={10.1609/aaai.v38i18.30041}, abstractNote={We introduce squared neural Poisson point processes (SNEPPPs) by parameterising the intensity function by the squared norm of a two layer neural network.
When the hidden layer is fixed and the second layer has a single neuron, our approach resembles previous uses of squared Gaussian process or kernel methods, but allowing the hidden layer to be learnt allows for additional flexibility.
In many cases of interest, the integrated intensity function admits a closed form and can be computed in quadratic time in the number of hidden neurons.
We enumerate a far more extensive number of such cases than has previously been discussed.
Our approach is more memory and time efficient than naive implementations of squared or exponentiated kernel methods or Gaussian processes.
Maximum likelihood and maximum a posteriori estimates in a reparameterisation of the final layer of the intensity function can be obtained by solving a (strongly) convex optimisation problem using projected gradient descent. We demonstrate SNEPPPs on real, and synthetic benchmarks, and provide a software implementation.}, number={18}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Tsuchida, Russell and Ong, Cheng Soon and Sejdinovic, Dino}, year={2024}, month={Mar.}, pages={20559-20566} }

@article{Zhong_Wei_Yang_Wang_2024, title={ExpCLIP: Bridging Text and Facial Expressions via Semantic Alignment}, volume={38}, url={https://ojs.aaai.org/index.php/AAAI/article/view/28594}, DOI={10.1609/aaai.v38i7.28594}, abstractNote={The objective of stylized speech-driven facial animation is to create animations that encapsulate specific emotional expressions. Existing methods often depend on pre-established emotional labels or facial expression templates, which may limit the necessary flexibility for accurately conveying user intent.
In this research, we introduce a technique that enables the control of arbitrary styles by leveraging natural language as emotion prompts. This technique presents benefits in terms of both flexibility and user-friendliness.
To realize this objective, we initially construct a Text-Expression Alignment Dataset (TEAD), wherein each facial expression is paired with several prompt-like descriptions. We propose an innovative automatic annotation method, supported by CahtGPT, to expedite the dataset construction, thereby eliminating the substantial expense of manual annotation.
Following this, we utilize TEAD to train a CLIP-based model, termed ExpCLIP, which encodes text and facial expressions into semantically aligned style embeddings. The embeddings are subsequently integrated into the facial animation generator to yield expressive and controllable facial animations. Given the limited diversity of facial emotions in existing speech-driven facial animation training data, we further introduce an effective Expression Prompt Augmentation (EPA) mechanism to enable the animation generator to support unprecedented richness in style control.
Comprehensive experiments illustrate that our method accomplishes expressive facial animation generation and offers enhanced flexibility in effectively conveying the desired style.}, number={7}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Zhong, Yicheng and Wei, Huawei and Yang, Peiji and Wang, Zhisheng}, year={2024}, month={Mar.}, pages={7614-7622} }

@article{Kim_Shim_Lee_Shim_2024, title={Expand-and-Quantize: Unsupervised Semantic Segmentation Using High-Dimensional Space and Product Quantization}, volume={38}, url={https://ojs.aaai.org/index.php/AAAI/article/view/28056}, DOI={10.1609/aaai.v38i3.28056}, abstractNote={Unsupervised semantic segmentation (USS) aims to discover and recognize meaningful categories without any labels. For a successful USS, two key abilities are required: 1) information compression and 2) clustering capability.
Previous methods have relied on feature dimension reduction for information compression, however, this approach may hinder the process of clustering.
In this paper, we propose a novel USS framework called Expand-and-Quantize Unsupervised Semantic Segmentation (EQUSS), which combines the benefits of high-dimensional spaces for better clustering and product quantization for effective information compression.
Our extensive experiments demonstrate that EQUSS achieves state-of-the-art results on three standard benchmarks.
In addition, we analyze the entropy of USS features, which is the first step towards understanding USS from the perspective of information theory.}, number={3}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Kim, Jiyoung and Shim, Kyuhong and Lee, Insu and Shim, Byonghyo}, year={2024}, month={Mar.}, pages={2768-2776} }

@article{Shi_Zhong_Liang_Li_Zhang_Li_2024, title={Explicit Visual Prompts for Visual Object Tracking}, volume={38}, url={https://ojs.aaai.org/index.php/AAAI/article/view/28286}, DOI={10.1609/aaai.v38i5.28286}, abstractNote={How to effectively exploit spatio-temporal information is crucial to capture target appearance changes in visual tracking. However, most deep learning-based trackers mainly focus on designing a complicated appearance model or template updating strategy, while lacking the exploitation of context between consecutive frames and thus entailing the when-and-how-to-update dilemma. To address these issues, we propose a novel explicit visual prompts framework for visual tracking, dubbed EVPTrack. Specifically, we utilize spatio-temporal tokens to propagate information between consecutive frames without focusing on updating templates. As a result, we cannot only alleviate the challenge of when-to-update, but also avoid the hyper-parameters associated with updating strategies. Then, we utilize the spatio-temporal tokens to generate explicit visual prompts that facilitate inference in the current frame. The prompts are fed into a transformer encoder together with the image tokens without additional processing.
Consequently, the efficiency of our model is improved by avoiding how-to-update. In addition, we consider multi-scale information as explicit visual prompts, providing multiscale template features to enhance the EVPTrack’s ability to handle target scale changes. Extensive experimental results on six benchmarks (i.e., LaSOT, LaSOText, GOT-10k, UAV123, TrackingNet, and TNL2K.) validate that our EVPTrack can achieve competitive performance at a real-time speed by effectively exploiting both spatio-temporal and multi-scale information. Code and models are available at
https://github.com/GXNU-ZhongLab/EVPTrack.}, number={5}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Shi, Liangtao and Zhong, Bineng and Liang, Qihua and Li, Ning and Zhang, Shengping and Li, Xianxian}, year={2024}, month={Mar.}, pages={4838-4846} }

@article{Shapira_Keller_2024, title={FaceCoresetNet: Differentiable Coresets for Face Set Recognition}, volume={38}, url={https://ojs.aaai.org/index.php/AAAI/article/view/28276}, DOI={10.1609/aaai.v38i5.28276}, abstractNote={In set-based face recognition, we aim to compute the most discriminative descriptor from an unbounded set of images and videos showing a single person. A discriminative descriptor balances two policies when aggregating information from a given set. The first is a quality-based policy: emphasizing high-quality and down-weighting low-quality images. The second is a diversity-based policy: emphasizing unique images in the set and down-weighting multiple occurrences of similar images as found in video clips which can overwhelm the set representation.
This work frames face-set representation as a differentiable coreset selection problem. Our model learns how to select a small coreset of the input set that balances quality and diversity policies using a learned metric parameterized by the face quality, optimized end-to-end. The selection process is a differentiable farthest-point sampling (FPS) realized by approximating the non-differentiable Argmax operation with differentiable sampling from the Gumbel-Softmax distribution of distances. The small coreset is later used as queries in a self and cross-attention architecture to enrich the descriptor with information from the whole set. Our model is order-invariant and linear in the input set size.
We set a new SOTA to set face verification on the IJB-B and IJB-C datasets. Our code is publicly available at https://github.com/ligaripash/FaceCoresetNet.}, number={5}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Shapira, Gil and Keller, Yosi}, year={2024}, month={Mar.}, pages={4748-4756} }

@article{Eliasof_Haber_Treister_2024, title={Feature Transportation Improves Graph Neural Networks}, volume={38}, url={https://ojs.aaai.org/index.php/AAAI/article/view/29073}, DOI={10.1609/aaai.v38i11.29073}, abstractNote={Graph neural networks (GNNs) have shown remarkable success in learning representations for graph-structured data. However, GNNs still face challenges in modeling complex phenomena that involve feature transportation. In this paper, we propose a novel GNN architecture inspired by Advection-Diffusion-Reaction systems, called ADR-GNN.
Advection models feature transportation, while diffusion captures the local smoothing of features, and reaction represents the non-linear transformation between feature channels. We provide an analysis of the qualitative behavior of ADR-GNN, that shows the benefit of combining advection, diffusion, and reaction.
To demonstrate its efficacy, we evaluate ADR-GNN on real-world node classification and spatio-temporal datasets, and show that it improves or offers competitive performance compared to state-of-the-art networks.}, number={11}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Eliasof, Moshe and Haber, Eldad and Treister, Eran}, year={2024}, month={Mar.}, pages={11874-11882} }

@article{Sun_Zhu_Yang_Wang_Fan_Zhu_Chen_2024, title={Fine-Tuning Graph Neural Networks by Preserving Graph Generative Patterns}, volume={38}, url={https://ojs.aaai.org/index.php/AAAI/article/view/28755}, DOI={10.1609/aaai.v38i8.28755}, abstractNote={Recently, the paradigm of pre-training and fine-tuning graph neural networks has been intensively studied and applied in a wide range of graph mining tasks. Its success is generally attributed to the structural consistency between pre-training and downstream datasets, which, however, does not hold in many real-world scenarios. Existing works have shown that the structural divergence between pre-training and downstream graphs significantly limits the transferability when using the vanilla fine-tuning strategy. This divergence leads to model overfitting on pre-training graphs and causes difficulties in capturing the structural properties of the downstream graphs. In this paper, we identify the fundamental cause of structural divergence as the discrepancy of generative patterns between the pre-training and downstream graphs.
Furthermore, we propose G-Tuning to preserve the generative patterns of downstream graphs. Given a downstream graph G, the core idea is to tune the pre-trained GNN so that it can reconstruct the generative patterns of G, the graphon W.
However, the exact reconstruction of a graphon is known to be computationally expensive. To overcome this challenge, we provide a theoretical analysis that establishes the existence of a set of alternative graphons called graphon bases for any given graphon. By utilizing a linear combination of these graphon bases, we can efficiently approximate W. This theoretical finding forms the basis of our model, as it enables effective learning of the graphon bases and their associated coefficients.
Compared with existing algorithms, G-Tuning demonstrates consistent performance improvement in 7 in-domain and 7 out-of-domain transfer learning experiments.}, number={8}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Sun, Yifei and Zhu, Qi and Yang, Yang and Wang, Chunping and Fan, Tianyu and Zhu, Jiajun and Chen, Lei}, year={2024}, month={Mar.}, pages={9053-9061} }

@article{Chen_Xu_Liao_Ding_Zhang_Yu_Zhao_2024, title={Focus-Then-Decide: Segmentation-Assisted Reinforcement Learning}, volume={38}, url={https://ojs.aaai.org/index.php/AAAI/article/view/29002}, DOI={10.1609/aaai.v38i10.29002}, abstractNote={Visual Reinforcement Learning (RL) is a promising approach to achieve human-like intelligence. However, it currently faces challenges in learning efficiently within noisy environments. In contrast, humans can quickly identify task-relevant objects in distraction-filled surroundings by applying previously acquired common knowledge. Recently, foundational models in natural language processing and computer vision have achieved remarkable successes, and the common knowledge within these models can significantly benefit downstream task training. Inspired by these achievements, we aim to incorporate common knowledge from foundational models into visual RL. We propose a novel Focus-Then-Decide (FTD) framework, allowing the agent to make decisions based solely on task-relevant objects. To achieve this, we introduce an attention mechanism to select task-relevant objects from the object set returned by a foundational segmentation model, and only use the task-relevant objects for the subsequent training of the decision module. Additionally, we specifically employed two generic self-supervised objectives to facilitate the rapid learning of this attention mechanism. Experimental results on challenging tasks based on DeepMind Control Suite and Franka Emika Robotics demonstrate that our method can quickly and accurately pinpoint objects of interest in noisy environments. Consequently, it achieves a significant performance improvement over current state-of-the-art algorithms.
Project Page: https://www.lamda.nju.edu.cn/chenc/FTD.html
Code: https://github.com/LAMDA-RL/FTD}, number={10}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Chen, Chao and Xu, Jiacheng and Liao, Weijian and Ding, Hao and Zhang, Zongzhang and Yu, Yang and Zhao, Rui}, year={2024}, month={Mar.}, pages={11240-11248} }

@article{Chen_Yang_Sun_Lan_Zhou_2024, title={From Coarse to Fine: A Distillation Method for Fine-Grained Emotion-Causal Span Pair Extraction in Conversation}, volume={38}, url={https://ojs.aaai.org/index.php/AAAI/article/view/29732}, DOI={10.1609/aaai.v38i16.29732}, abstractNote={We study the problem of extracting emotions and the causes behind these emotions in conversations.
Existing methods either tackle them separately or jointly model them at the coarse-grained level of emotions (fewer emotion categories) and causes (utterance-level causes). In this work, we aim to jointly extract more fine-grained emotions and causes.
We construct a fine-grained dataset FG-RECCON, includes 16 fine-grained emotion categories and span-level causes.
To further improve the fine-grained extraction performance, we propose to utilize the casual discourse knowledge in a knowledge distillation way.
Specifically, the teacher model learns to predict causal connective words between utterances, and then guides the student model in identifying both the fine-grained emotion labels and causal spans.
Experimental results demonstrate that our distillation method achieves state-of-the-art performance on both RECCON and FG-RECCON dataset.}, number={16}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Chen, Xinhao and Yang, Chong and Sun, Changzhi and Lan, Man and Zhou, Aimin}, year={2024}, month={Mar.}, pages={17790-17798} }

@article{Dutta_Pandey_Singh_Manchanda_Chakrabarti_Chakraborty_2024, title={Frugal LMs Trained to Invoke Symbolic Solvers Achieve Parameter-Efficient Arithmetic Reasoning}, volume={38}, url={https://ojs.aaai.org/index.php/AAAI/article/view/29750}, DOI={10.1609/aaai.v38i16.29750}, abstractNote={Large Language Models (LLM) exhibit zero-shot mathematical reasoning capacity as a behavior emergent with scale, commonly manifesting as chain-of-thoughts (CoT) reasoning. However, multiple empirical findings suggest that this prowess is exclusive to LLMs that have exorbitant sizes (beyond 50 billion parameters). Meanwhile, educational neuroscientists suggest that symbolic algebraic manipulation be introduced around the same time as arithmetic word problems so as to modularize language-to-formulation, symbolic manipulation of the formulation, and endgame arithmetic.
In this paper, we start with the hypothesis that much smaller LMs, which are weak at multi-step reasoning, can achieve reasonable arithmetic reasoning if arithmetic word problems are posed as a formalize-then-solve task.
In our architecture, which we call SyReLM, the LM serves the role of a translator to map natural language arithmetic questions into a formal language (FL) description. A symbolic solver then evaluates the FL expression to obtain the answer.
A small frozen LM, equipped with an efficient low-rank adapter, is capable of generating FL expressions that incorporate natural language descriptions of the arithmetic problem (e.g., variable names and their purposes, formal expressions combining variables, etc.).
We adopt policy-gradient reinforcement learning to train the adapted LM, informed by the non-differentiable symbolic solver. This marks a sharp departure from the recent development in tool-augmented LLMs, in which the external tools (e.g., calculator, Web search, etc.) are essentially detached from the learning phase of the LM. SyReLM shows massive improvements (e.g., +30.65 absolute point improvement in accuracy on the SVAMP dataset using GPT-J 6B model) over base LMs, while keeping our testbed easy to diagnose and interpret, and within the reach of most researchers.}, number={16}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Dutta, Subhabrata and Pandey, Ishan and Singh, Joykirat and Manchanda, Sunny and Chakrabarti, Soumen and Chakraborty, Tanmoy}, year={2024}, month={Mar.}, pages={17951-17959} }

@article{Song_Su_Zheng_Zhang_Liu_Liu_2024, title={Generalizable Fourier Augmentation for Unsupervised Video Object Segmentation}, volume={38}, url={https://ojs.aaai.org/index.php/AAAI/article/view/28295}, DOI={10.1609/aaai.v38i5.28295}, abstractNote={The performance of existing unsupervised video object segmentation methods typically suffers from severe performance degradation on test videos when tested in out-of-distribution scenarios. The primary reason is that the test data in real-
world may not follow the independent and identically distribution (i.i.d.) assumption, leading to domain shift. In this paper, we propose a generalizable fourier augmentation method during training to improve the generalization ability of the model. To achieve this, we perform Fast Fourier Transform (FFT) over the intermediate spatial domain features in each layer to yield corresponding frequency representations, including amplitude components (encoding scene-aware styles such as texture, color, contrast of the scene) and phase components (encoding rich semantics). We produce a variety of style features via Gaussian sampling to augment the training data, thereby improving the generalization capability of the model. To further improve the cross-domain generalization
performance of the model, we design a phase feature update strategy via exponential moving average using phase features from past frames in an online update manner, which could help the model to learn cross-domain-invariant features. Extensive experiments show that our proposed method achieves
the state-of-the-art performance on popular benchmarks.}, number={5}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Song, Huihui and Su, Tiankang and Zheng, Yuhui and Zhang, Kaihua and Liu, Bo and Liu, Dong}, year={2024}, month={Mar.}, pages={4918-4924} }

@article{Jia_Li_Yang_Tao_Shi_2024, title={Graph Invariant Learning with Subgraph Co-mixup for Out-of-Distribution Generalization}, volume={38}, url={https://ojs.aaai.org/index.php/AAAI/article/view/28700}, DOI={10.1609/aaai.v38i8.28700}, abstractNote={Graph neural networks (GNNs) have been demonstrated to perform well in graph representation learning, but always lacking in generalization capability when tackling out-of-distribution (OOD) data. Graph invariant learning methods, backed by the invariance principle among defined multiple environments, have shown effectiveness in dealing with this issue. However, existing methods heavily rely on well-predefined or accurately generated environment partitions, which are hard to be obtained in practice, leading to sub-optimal OOD generalization performances.
In this paper, we propose a novel graph invariant learning method based on invariant and variant patterns co-mixup strategy, which is capable of jointly generating mixed multiple environments and capturing invariant patterns from the mixed graph data. Specifically, we first adopt a subgraph extractor to identify invariant subgraphs. Subsequently, we design one novel co-mixup strategy, i.e., jointly conducting environment mixup and invariant mixup. For the environment mixup, we mix the variant environment-related subgraphs so as to generate sufficiently diverse multiple environments, which is important to guarantee the quality of the graph invariant learning. For the invariant mixup, we mix the invariant subgraphs, further encouraging to capture invariant patterns behind graphs while getting rid of spurious correlations for OOD generalization. We demonstrate that the proposed environment mixup and invariant mixup can mutually promote each other.
Extensive experiments on both synthetic and real-world datasets demonstrate that our method significantly outperforms state-of-the-art under various distribution shifts.}, number={8}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Jia, Tianrui and Li, Haoyang and Yang, Cheng and Tao, Tao and Shi, Chuan}, year={2024}, month={Mar.}, pages={8562-8570} }

@article{Yu_Fang_Liu_Zhang_2024, title={HGPrompt: Bridging Homogeneous and Heterogeneous Graphs for Few-Shot Prompt Learning}, volume={38}, url={https://ojs.aaai.org/index.php/AAAI/article/view/29596}, DOI={10.1609/aaai.v38i15.29596}, abstractNote={Graph neural networks (GNNs) and heterogeneous graph neural networks (HGNNs) are prominent techniques for homogeneous and heterogeneous graph representation learning, yet their performance in an end-to-end supervised framework greatly depends on the availability of task-specific supervision. To reduce the labeling cost, pre-training on self-supervised pretext tasks has become a popular paradigm, but there is often a gap between the pre-trained model and downstream tasks, stemming from the divergence in their objectives. To bridge the gap, prompt learning has risen as a promising direction especially in few-shot settings, without the need to fully fine-tune the pre-trained model. While there has been some early exploration of prompt-based learning on graphs, they primarily deal with homogeneous graphs, ignoring the heterogeneous graphs that are prevalent in downstream applications. In this paper, we propose HGPROMPT, a
novel pre-training and prompting framework to unify not only pre-training and downstream tasks but also homogeneous and heterogeneous graphs via a dual-template design. Moreover, we propose dual-prompt in HGPROMPT to assist a downstream task in locating the most relevant prior to bridge the gaps caused by not only feature variations but also heterogeneity differences across tasks. Finally, we thoroughly evaluate and analyze HGPROMPT through extensive experiments
on three public datasets.}, number={15}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Yu, Xingtong and Fang, Yuan and Liu, Zemin and Zhang, Xinming}, year={2024}, month={Mar.}, pages={16578-16586} }

@article{Ryu_Joo_Jang_Yang_2024, title={Instance-Wise Laplace Mechanism via Deep Reinforcement Learning (Student Abstract)}, volume={38}, url={https://ojs.aaai.org/index.php/AAAI/article/view/30506}, DOI={10.1609/aaai.v38i21.30506}, abstractNote={Recent research has shown a growing interest in per-instance differential privacy (pDP), highlighting the fact that each data instance within a dataset may incur distinct levels of privacy loss.
However, conventional additive noise mechanisms apply identical noise to all query outputs, thereby deteriorating data statistics.
In this study, we propose an instance-wise Laplace mechanism, which adds non-identical Laplace noises to the query output for each data instance.
A challenge arises from the complex interaction of additive noise, where the noise introduced to individual instances impacts the pDP of other instances, adding complexity and resilience to straightforward solutions.
To tackle this problem, we introduce an instance-wise Laplace mechanism algorithm via deep reinforcement learning and validate its ability to better preserve data statistics on a real dataset, compared to the original Laplace mechanism.}, number={21}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Ryu, Sehyun and Joo, Hosung and Jang, Jonggyu and Yang, Hyun Jong}, year={2024}, month={Mar.}, pages={23640-23641} }

@article{Gu_Sah_Gopalan_2024, title={Interactive Visual Task Learning for Robots}, volume={38}, url={https://ojs.aaai.org/index.php/AAAI/article/view/30567}, DOI={10.1609/aaai.v38i21.30567}, abstractNote={We present a demonstrable framework for robots to learn novel visual concepts and visual tasks via in-situ linguistic interactions with human users. Previous approaches in computer vision have either used large pre-trained visual models to infer novel objects zero-shot, or added novel concepts along with their attributes and representations to a concept hierarchy. We extend the approaches that focus on learning visual concept hierarchies and take this ability one step further to demonstrate novel task solving on robots along with the learned visual concepts. To enable a visual concept learner to solve robotics tasks one-shot, we developed two distinct techniques.
Firstly, we propose a novel approach, Hi-Viscont(HIerarchical VISual CONcept learner for Task), which augments information of a novel concept, that is being taught, to its parent nodes within a concept hierarchy. This information propagation allows all concepts in a hierarchy to update as novel concepts are taught in a continual learning setting. Secondly, we represent a visual task as a scene graph with language annotations, allowing us to create novel permutations of a demonstrated task zero-shot in-situ. Combining the two techniques, we present a demonstration on a real robot that learns visual task and concepts in one-shot from in-situ interactions with human users, and generalize to perform a novel visual task of the same type in zero-shot.
As shown by the studies in the main conference paper, our system achieves a success rate of 50% on solving the whole task correctly with generalization where the baseline performs at 14% without any ability to generalize to novel tasks and concepts. We will demonstrate our working interactive learning pipeline at AAAI 2024 in person with our robot and other required hardware.}, number={21}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Gu, Weiwei and Sah, Anant and Gopalan, Nakul}, year={2024}, month={Mar.}, pages={23793-23795} }

@article{de Vazelhes_Mukhoty_Yuan_Gu_2024, title={Iterative Regularization with k-support Norm: An Important Complement to Sparse Recovery}, volume={38}, url={https://ojs.aaai.org/index.php/AAAI/article/view/29057}, DOI={10.1609/aaai.v38i10.29057}, abstractNote={Sparse recovery is ubiquitous in machine learning and signal processing. Due to the NP-hard nature of sparse recovery, existing methods are known to suffer either from restrictive (or even unknown) applicability conditions, or high computational cost. Recently, iterative regularization methods have emerged as a promising fast approach because they can achieve sparse recovery in one pass through early stopping, rather than the tedious grid-search used in the traditional methods.
However, most of those iterative methods are based on the l1 norm which requires restrictive applicability conditions and could fail in many cases. Therefore, achieving sparse recovery with iterative regularization methods under a wider range of conditions has yet to be further explored.
To address this issue, we propose a novel iterative regularization algorithm, IRKSN, based on the k-support norm regularizer rather than the l1 norm. We provide conditions for sparse recovery with IRKSN, and compare them with traditional conditions for recovery with l1 norm regularizers. Additionally, we give an early stopping bound on the model error of IRKSN with explicit constants, achieving the standard linear rate for sparse recovery. Finally, we illustrate the applicability of our algorithm on several experiments, including a support recovery experiment with a correlated design matrix.}, number={10}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={de Vazelhes, William and Mukhoty, Bhaskar and Yuan, Xiao-Tong and Gu, Bin}, year={2024}, month={Mar.}, pages={11731-11739} }

@article{Wang_Chang_Zhai_Luo_Sun_Lin_Tian_2024, title={LION: Implicit Vision Prompt Tuning}, volume={38}, url={https://ojs.aaai.org/index.php/AAAI/article/view/28345}, DOI={10.1609/aaai.v38i6.28345}, abstractNote={Despite recent promising performances across a range of vision tasks, vision Transformers still have an issue of high computational costs.
Recently, vision prompt learning has provided an economical solution to this problem without fine-tuning the whole large-scale model. However, the efficiency and effectiveness of existing models are still far from satisfactory due to the parameter cost of extensive prompt blocks and tricky prompt framework designs. In this paper, we propose a light-weight prompt framework named impLicit vIsion prOmpt tuNing (LION), which is motivated by deep implicit models with stable low memory costs for various complex tasks.
In particular, we merely insect two equilibrium implicit layers in two ends of the pre-trained backbone with parameters frozen. Moreover, according to the lottery hypothesis, we further prune the parameters to relieve the computation burden in implicit layers. Various experiments have validated that our LION obtains promising performances on a wide range of datasets. Most importantly, LION reduces up to 11.5 % of training parameter numbers while obtaining higher performance than the state-of-the-art VPT, especially under challenging scenes. Furthermore, we find that our proposed LION has an excellent generalization performance, making it an easy way to boost transfer learning in the future.}, number={6}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Wang, Haixin and Chang, Jianlong and Zhai, Yihang and Luo, Xiao and Sun, Jinan and Lin, Zhouchen and Tian, Qi}, year={2024}, month={Mar.}, pages={5372-5380} }

@article{Zhang_Zhang_Yuan_Liu_Shi_Gui_Zhang_Huang_2024, title={LLMEval: A Preliminary Study on How to Evaluate Large Language Models}, volume={38}, url={https://ojs.aaai.org/index.php/AAAI/article/view/29934}, DOI={10.1609/aaai.v38i17.29934}, abstractNote={Recently, the evaluation of Large Language Models has emerged as a popular area of research. The three crucial questions for LLM evaluation are ``what, where, and how to evaluate’’.
However, the existing research mainly focuses on the first two questions, which are basically what tasks to give the LLM during testing and what kind of knowledge it should deal with.
As for the third question, which is about what standards to use, the types of evaluators, how to score, and how to rank, there hasn’t been much discussion.
In this paper, we analyze evaluation methods by comparing various criteria with both manual and automatic evaluation, utilizing onsite, crowd-sourcing, public annotators and GPT-4, with different scoring methods and ranking systems. We propose a new dataset, LLMEval and conduct evaluations on 20 LLMs. A total of 2,186 individuals participated, leading to the generation of 243,337 manual annotations and 57,511 automatic evaluation results.
We perform comparisons and analyses of different settings and conduct 10 conclusions that can provide some insights for evaluating LLM in the future. The dataset and the results are publicly available at https://github.com/llmeval.
The version with the appendix are publicly available at https://arxiv.org/abs/2312.07398.}, number={17}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Zhang, Yue and Zhang, Ming and Yuan, Haipeng and Liu, Shichun and Shi, Yongyao and Gui, Tao and Zhang, Qi and Huang, Xuanjing}, year={2024}, month={Mar.}, pages={19615-19622} }

@article{Bi_Yi_Zheng_Ji_Huang_Li_Zheng_2024, title={Learning Generalized Medical Image Segmentation from Decoupled Feature Queries}, volume={38}, url={https://ojs.aaai.org/index.php/AAAI/article/view/27839}, DOI={10.1609/aaai.v38i2.27839}, abstractNote={Domain generalized medical image segmentation requires models to learn from multiple source domains and generalize well to arbitrary unseen target domain. Such a task is both technically challenging and clinically practical, due to the domain shift problem (i.e., images are collected from different hospitals and scanners). Existing methods focused on either learning shape-invariant representation or reaching consensus among the source domains. An ideal generalized representation is supposed to show similar pattern responses within the same channel for cross-domain images.
However, to deal with the significant distribution discrepancy, the network tends to capture similar patterns by multiple channels, while different cross-domain patterns are also allowed to rest in the same channel. To address this issue, we propose to leverage channel-wise decoupled deep features as queries. With the aid of cross-attention mechanism, the long-range dependency between deep and shallow features can be fully mined via self-attention and then guides the learning of generalized representation. Besides, a relaxed deep whitening transformation is proposed to learn channel-wise decoupled features in a feasible way. The proposed decoupled fea-
ture query (DFQ) scheme can be seamlessly integrate into the Transformer segmentation model in an end-to-end manner. Extensive experiments show its state-of-the-art performance, notably outperforming the runner-up by 1.31% and 1.98% with DSC metric on generalized fundus and prostate benchmarks, respectively. Source code is available at https://github.com/BiQiWHU/DFQ.}, number={2}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Bi, Qi and Yi, Jingjun and Zheng, Hao and Ji, Wei and Huang, Yawen and Li, Yuexiang and Zheng, Yefeng}, year={2024}, month={Mar.}, pages={810-818} }

@article{Sychrovský_Šustr_Davoodi_Bowling_Lanctot_Schmid_2024, title={Learning Not to Regret}, volume={38}, url={https://ojs.aaai.org/index.php/AAAI/article/view/29443}, DOI={10.1609/aaai.v38i14.29443}, abstractNote={The literature on game-theoretic equilibrium finding predominantly focuses on single games or their repeated play.
Nevertheless, numerous real-world scenarios feature playing a game sampled from a distribution of similar, but not identical games, such as playing poker with different public cards or trading correlated assets on the stock market. As these similar games feature similar equilibra, we investigate a way to accelerate equilibrium finding on such a distribution.
We present a novel ``learning not to regret’’ framework, enabling us to meta-learn a regret minimizer tailored to a specific distribution. Our key contribution, Neural Predictive Regret Matching, is uniquely meta-learned to converge rapidly for the chosen distribution of games, while having regret minimization guarantees on any game.
We validated our algorithms’ faster convergence on a distribution of river poker games. Our experiments show that the meta-learned algorithms outpace their non-meta-learned counterparts, achieving more than tenfold improvements.}, number={14}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Sychrovský, David and Šustr, Michal and Davoodi, Elnaz and Bowling, Michael and Lanctot, Marc and Schmid, Martin}, year={2024}, month={Mar.}, pages={15202-15210} }

@article{Tsouros_Berden_Guns_2024, title={Learning to Learn in Interactive Constraint Acquisition}, volume={38}, url={https://ojs.aaai.org/index.php/AAAI/article/view/28655}, DOI={10.1609/aaai.v38i8.28655}, abstractNote={Constraint Programming (CP) has been successfully used to model and solve complex combinatorial problems. However, modeling is often not trivial and requires expertise, which is a bottleneck to wider adoption. In Constraint Acquisition (CA), the goal is to assist the user by automatically learning the model.
In (inter)active CA, this is done by interactively posting queries to the user, e.g. does this partial solution satisfy your (unspecified) constraints or not.
While interactive CA methods learn the constraints, the learning is related to symbolic concept learning, as the goal is to learn an exact representation. However, a large number of queries is required to learn the model, which is a major limitation. In this paper, we aim to alleviate this limitation by tightening the connection of CA and Machine Learning (ML), by, for the first time in interactive CA, exploiting statistical ML methods. We propose to use probabilistic classification models to guide interactive CA queries to the most promising parts. We discuss how to train classifiers to predict whether a candidate expression from the bias is a constraint of the problem or not, using both relation-based and scope-based features. We then show how the predictions can be used in all layers of interactive CA: the query generation, the scope finding, and the lowest-level constraint finding. We experimentally evaluate our proposed methods using different classifiers and show that our methods greatly outperform the state of the art, decreasing the number of queries needed to converge by up to 72%.}, number={8}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Tsouros, Dimosthenis and Berden, Senne and Guns, Tias}, year={2024}, month={Mar.}, pages={8154-8162} }

@article{Greco_Scarcello_2024, title={Maxileximin Envy Allocations and Connected Goods}, volume={38}, url={https://ojs.aaai.org/index.php/AAAI/article/view/28829}, DOI={10.1609/aaai.v38i9.28829}, abstractNote={Fair allocation of indivisible goods presents intriguing challenges from both a social choice perspective and an algorithmic standpoint. Due to the indivisibility of goods, it is common for one agent to envy the bundle of goods assigned to another agent and, indeed, envy-free solutions do not exist in general. In line with the classical game-theoretic concept of Nucleolus in coalitional games, we propose that a fair allocation should minimize the agents’ dissatisfaction profile in a lexicographic manner, where the dissatisfaction of an agent is defined as her maximum envy towards other agents. Therefore, we seek allocations that minimize the maximum envy. In cases where multiple solutions have an equal maximum value, we minimize the second-worst value, and so on. Additionally, as is customary in fair division problems, we also consider an efficiency requirement: among the allocations with the best agents’ dissatisfaction profile, we prioritize those that maximize the sum of agents’ utilities, known as maximum social welfare. Such allocations, referred to as maxileximin allocations, always exist.
In this study, we analyze the computational properties of maxileximin allocations in the context of fair allocation problems with constraints. Specifically, we focus on the Connected Fair Division problem, where goods correspond to the nodes of a graph, and a bundle of goods is allowed if the subgraph formed by those goods is connected. We demonstrate that the problem is F∆P2 -complete, even for instances with simple graphical structures such as path and star graphs.
However, we identify islands of tractability for instances with more intricate graphs, such as those having bounded treewidth, provided that the number of agents is bounded by a fixed number and utility functions use small values.}, number={9}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Greco, Gianluigi and Scarcello, Francesco}, year={2024}, month={Mar.}, pages={9713-9721} }

@article{Neller_Bideau_Bierbach_Hönig_Lipovetzky_Muise_Coria_Wong_Rosenthal_Lu_Gao_Zhang_2024, title={Model AI Assignments 2024}, volume={38}, url={https://ojs.aaai.org/index.php/AAAI/article/view/30386}, DOI={10.1609/aaai.v38i21.30386}, abstractNote={The Model AI Assignments session seeks to gather and dis-
seminate the best assignment designs of the Artificial In-
telligence (AI) Education community. Recognizing that as-
signments form the core of student learning experience, we here present abstracts of five AI assignments from the 2024
session that are easily adoptable, playfully engaging, and flexible for a variety of instructor needs. Assignment spec-
ifications and supporting resources may be found at http://modelai.gettysburg.edu.}, number={21}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Neller, Todd W. and Bideau, Pia and Bierbach, David and Hönig, Wolfgang and Lipovetzky, Nir and Muise, Christian and Coria, Lino and Wong, Claire and Rosenthal, Stephanie and Lu, Yu and Gao, Ming and Zhang, Jingjing}, year={2024}, month={Mar.}, pages={23370-23371} }

@article{Lee_Ka_Choi_Kim_2024, title={Modeling Stereo-Confidence out of the End-to-End Stereo-Matching Network via Disparity Plane Sweep}, volume={38}, url={https://ojs.aaai.org/index.php/AAAI/article/view/28071}, DOI={10.1609/aaai.v38i4.28071}, abstractNote={We propose a novel stereo-confidence that can be measured externally to various stereo-matching networks, offering an alternative input modality choice of the cost volume for learning-based approaches, especially in safety-critical systems.
Grounded in the foundational concepts of disparity definition and the disparity plane sweep, the proposed stereo-confidence method is built upon the idea that any shift in a stereo-image pair should be updated in a corresponding amount shift in the disparity map. Based on this idea, the proposed stereo-confidence method can be summarized in three folds.
1) Using the disparity plane sweep, multiple disparity maps can be obtained and treated as a 3-D volume (predicted disparity volume), like the cost volume is constructed. 2) One of these disparity maps serves as an anchor, allowing us to define a desirable (or ideal) disparity profile at every spatial point.
3) By comparing the desirable and predicted disparity profiles, we can quantify the level of matching ambiguity between left and right images for confidence measurement. Extensive experimental results using various stereo-matching networks and datasets demonstrate that the proposed stereo-confidence method not only shows competitive performance on its own but also consistent performance improvements when it is used as an input modality for learning-based stereo-confidence methods.}, number={4}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Lee, Jae Young and Ka, Woonghyun and Choi, Jaehyun and Kim, Junmo}, year={2024}, month={Mar.}, pages={2901-2910} }

@article{Turutov_Radinsky_2024, title={Molecular Optimization Model with Patentability Constraint}, volume={38}, url={https://ojs.aaai.org/index.php/AAAI/article/view/27778}, DOI={10.1609/aaai.v38i1.27778}, abstractNote={In drug development, molecular optimization is a crucial challenge that involves generating novel molecules given a lead molecule as input. The task requires maintaining molecular similarity to the original molecule while simultaneously optimizing multiple chemical attributes. To aid in this process, numerous generative models have been proposed.
However, in practical applications, it is crucial for these models not only to generate novel molecules with the above constraints but also to generate molecules that significantly differ from any existing patented compounds. In this work, we present a multi-optimization molecular framework to address this challenge.
Our framework trains a model to prioritize both enhanced properties and substantial dissimilarity from patented compounds. By jointly learning continuous representations of optimized and patentable molecules, we ensure that the generated molecules are significantly distant from any patented compounds while improving chemical properties.
Through empirical evaluation, we demonstrate the superior performance of our approach compared to state-of-the-art molecular optimization methods both in chemical property optimization and patentability.}, number={1}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Turutov, Sally and Radinsky, Kira}, year={2024}, month={Mar.}, pages={257-264} }

@article{Nguyen_Liebowitz_Kanhere_Nepal_2024, title={Multiple Hypothesis Dropout: Estimating the Parameters of Multi-Modal Output Distributions}, volume={38}, url={https://ojs.aaai.org/index.php/AAAI/article/view/29358}, DOI={10.1609/aaai.v38i13.29358}, abstractNote={In many real-world applications, from robotics to pedestrian trajectory prediction, there is a need to predict multiple real-valued outputs to represent several potential scenarios. Current deep learning techniques to address multiple-output problems are based on two main methodologies: (1) mixture density networks, which suffer from poor stability at high dimensions, or (2) multiple choice learning (MCL), an approach that uses M single-output functions, each only producing a point estimate hypothesis. This paper presents a Mixture of Multiple-Output functions (MoM) approach using a novel variant of dropout, Multiple Hypothesis Dropout. Unlike traditional MCL-based approaches, each multiple-output function not only estimates the mean but also the variance for its hypothesis. This is achieved through a novel stochastic winner-take-all loss which allows each multiple-output function to estimate variance through the spread of its subnetwork predictions.
Experiments on supervised learning problems illustrate that our approach outperforms existing solutions for reconstructing multimodal output distributions.
Additional studies on unsupervised learning problems show that estimating the parameters of latent posterior distributions within a discrete autoencoder significantly improves codebook efficiency, sample quality, precision and recall.}, number={13}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Nguyen, David D. and Liebowitz, David and Kanhere, Salil S. and Nepal, Surya}, year={2024}, month={Mar.}, pages={14440-14448} }

@article{Fan_Tian_Dubey_Deshmukh_Murch_Chen_2024, title={Multitarget Device-Free Localization via Cross-Domain Wi-Fi RSS Training Data and Attentional Prior Fusion}, volume={38}, url={https://ojs.aaai.org/index.php/AAAI/article/view/27759}, DOI={10.1609/aaai.v38i1.27759}, abstractNote={Device-free localization (DFL) using easily-obtained Wi-Fi received signal strength (RSS) has wide real-world applications for not requiring people to carry trackable devices.
However, accurate multitarget DFL remains challenging due to the unknown number of targets, multipath interference (MPI), especially between nearby targets, and limited real-world data. In this study, we pioneeringly propose a transformer-based learning method with Wi-Fi RSS as input, and an attentional prior fusion module, to simultaneously locate an unknown number of people at random positions. To overcome the multitarget data collection challenges, we contribute a large-scale cross-domain real-simulation-augmentation training dataset with one and two real-world nearby non-person objects at limited positions and up to five simulated and augmented randomly distributed targets.
Experimental results demonstrate our method’s improved accuracy, generalization ability, and robustness with fewer Wi-Fi nodes than previous methods.}, number={1}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Fan, Na and Tian, Zeyue and Dubey, Amartansh and Deshmukh, Samruddhi and Murch, Ross and Chen, Qifeng}, year={2024}, month={Mar.}, pages={91-99} }

@article{Ye_Yu_Liu_Wang_2024, title={Mutual-Modality Adversarial Attack with Semantic Perturbation}, volume={38}, url={https://ojs.aaai.org/index.php/AAAI/article/view/28488}, DOI={10.1609/aaai.v38i7.28488}, abstractNote={Adversarial attacks constitute a notable threat to machine learning systems, given their potential to induce erroneous predictions and classifications. However, within real-world contexts, the essential specifics of the deployed model are frequently treated as a black box, consequently mitigating the vulnerability to such attacks.
Thus, enhancing the transferability of the adversarial samples has become a crucial area of research, which heavily relies on selecting appropriate surrogate models.
To address this challenge, we propose a novel approach that generates adversarial attacks in a mutual-modality optimization scheme. Our approach is accomplished by leveraging the pre-trained CLIP model. Firstly, we conduct a visual attack on the clean image that causes semantic perturbations on the aligned embedding space with the other textual modality. Then, we apply the corresponding defense on the textual modality by updating the prompts, which forces the re-matching on the perturbed embedding space. Finally, to enhance the attack transferability, we utilize the iterative training strategy on the visual attack and the textual defense, where the two processes optimize from each other.
We evaluate our approach on several benchmark datasets and demonstrate that our mutual-modal attack strategy can effectively produce high-transferable attacks, which are stable regardless of the target networks. Our approach outperforms state-of-the-art attack methods and can be readily deployed as a plug-and-play solution.}, number={7}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Ye, Jingwen and Yu, Ruonan and Liu, Songhua and Wang, Xinchao}, year={2024}, month={Mar.}, pages={6657-6665} }

@article{Tian_Li_Li_Wang_2024, title={N-gram Unsupervised Compoundation and Feature Injection for Better Symbolic Music Understanding}, volume={38}, url={https://ojs.aaai.org/index.php/AAAI/article/view/29461}, DOI={10.1609/aaai.v38i14.29461}, abstractNote={The first step to apply deep learning techniques for symbolic music understanding is to transform musical pieces (mainly in MIDI format) into sequences of predefined tokens like note pitch, note velocity, and chords. Subsequently, the sequences are fed into a neural sequence model to accomplish specific tasks.
Music sequences exhibit strong correlations between adjacent elements, making them prime candidates for N-gram techniques from Natural Language Processing (NLP). Consider classical piano music: specific melodies might recur throughout a piece, with subtle variations each time.
In this paper, we propose a novel method, NG-Midiformer, for understanding symbolic music sequences that leverages the N-gram approach. Our method involves first processing music pieces into word-like sequences with our proposed unsupervised compoundation, followed by using our N-gram Transformer encoder, which can effectively incorporate N-gram information to enhance the primary encoder part for better understanding of music sequences.
The pre-training process on large-scale music datasets enables the model to thoroughly learn the N-gram information contained within music sequences, and subsequently apply this information for making inferences during the fine-tuning stage.
Experiment on various datasets demonstrate the effectiveness of our method and achieved state-of-the-art performance on a series of music understanding downstream tasks. The code and model weights will be released at https://github.com/CinqueOrigin/NG-Midiformer.}, number={14}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Tian, Jinhao and Li, Zuchao and Li, Jiajia and Wang, Ping}, year={2024}, month={Mar.}, pages={15364-15372} }

@article{Dang_Luo_Jia_Dai_Chang_Wang_2024, title={Noisy Correspondence Learning with Self-Reinforcing Errors Mitigation}, volume={38}, url={https://ojs.aaai.org/index.php/AAAI/article/view/27911}, DOI={10.1609/aaai.v38i2.27911}, abstractNote={Cross-modal retrieval relies on well-matched large-scale datasets that are laborious in practice. Recently, to alleviate expensive data collection, co-occurring pairs from the Internet are automatically harvested for training.
However, it inevitably includes mismatched pairs, i.e., noisy correspondences, undermining supervision reliability and degrading performance. Current methods leverage deep neural networks’ memorization effect to address noisy correspondences, which overconfidently focus on similarity-guided training with hard negatives and suffer from self-reinforcing errors. In light of above, we introduce a novel noisy correspondence learning framework, namely Self-Reinforcing Errors Mitigation (SREM).
Specifically, by viewing sample matching as classification tasks within the batch, we generate classification logits for the given sample. Instead of a single similarity score, we refine sample filtration through energy uncertainty and estimate model’s sensitivity of selected clean samples using swapped classification entropy, in view of the overall prediction distribution. Additionally, we propose cross-modal biased complementary learning to leverage negative matches overlooked in hard-negative training, further improving model optimization stability and curbing self-reinforcing errors. Extensive experiments on challenging benchmarks affirm the efficacy and efficiency of SREM.}, number={2}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Dang, Zhuohang and Luo, Minnan and Jia, Chengyou and Dai, Guang and Chang, Xiaojun and Wang, Jingdong}, year={2024}, month={Mar.}, pages={1463-1471} }

@article{Dold_Helmert_2024, title={Novelty vs. Potential Heuristics: A Comparison of Hardness Measures for Satisficing Planning}, volume={38}, url={https://ojs.aaai.org/index.php/AAAI/article/view/30056}, DOI={10.1609/aaai.v38i18.30056}, abstractNote={Classical planning considers a given task and searches for a plan to solve it. Some tasks are harder to solve than others. We can measure the ’hardness’ of a task with the novelty width and the correlation complexity. In this work, we compare these measures.
Additionally, we introduce the river measure, a new measure that is based on potential heuristics and therefore similar to the correlation complexity but also comparable to the novelty width.
We show that the river measure is upper bounded by the correlation complexity and by the novelty width +1. Furthermore, we show that we can convert a planning task with a polynomial blowup of the task size to ensure that a heuristic of dimension 2 exists that gives rise to backtrack-free search.}, number={18}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Dold, Simon and Helmert, Malte}, year={2024}, month={Mar.}, pages={20692-20699} }

@article{Wu_Zhang_Yi_Gao_Guo_Peng_Lan_Han_Pan_Yuan_Jin_Chen_Chen_Li_2024, title={OCEAN-MBRL: Offline Conservative Exploration for Model-Based Offline Reinforcement Learning}, volume={38}, url={https://ojs.aaai.org/index.php/AAAI/article/view/29520}, DOI={10.1609/aaai.v38i14.29520}, abstractNote={Model-based offline reinforcement learning (RL) algorithms have emerged as a promising paradigm for offline RL.
These algorithms usually learn a dynamics model from a static dataset of transitions, use the model to generate synthetic trajectories, and perform conservative policy optimization within these trajectories. However, our observations indicate that policy optimization methods used in these model-based offline RL algorithms are not effective at exploring the learned model and induce biased exploration, which ultimately impairs the performance of the algorithm.
To address this issue, we propose Offline Conservative ExplorAtioN (OCEAN), a novel rollout approach to model-based offline RL.
In our method, we incorporate additional exploration techniques and introduce three conservative constraints based on uncertainty estimation to mitigate the potential impact of significant dynamic errors resulting from exploratory transitions. Our work is a plug-in method and can be combined with classical model-based RL algorithms, such as MOPO, COMBO, and RAMBO.
Experiment results of our method on the D4RL MuJoCo benchmark show that OCEAN significantly improves the performance of existing algorithms.}, number={14}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Wu, Fan and Zhang, Rui and Yi, Qi and Gao, Yunkai and Guo, Jiaming and Peng, Shaohui and Lan, Siming and Han, Husheng and Pan, Yansong and Yuan, Kaizhao and Jin, Pengwei and Chen, Ruizhi and Chen, Yunji and Li, Ling}, year={2024}, month={Mar.}, pages={15897-15905} }

@article{Hu_Ye_Zhao_Lin_He_Wen_He_Liu_2024, title={O^2-Recon: Completing 3D Reconstruction of Occluded Objects in the Scene with a Pre-trained 2D Diffusion Model}, volume={38}, url={https://ojs.aaai.org/index.php/AAAI/article/view/28002}, DOI={10.1609/aaai.v38i3.28002}, abstractNote={Occlusion is a common issue in 3D reconstruction from RGB-D videos, often blocking the complete reconstruction of objects and presenting an ongoing problem. In this paper, we propose a novel framework, empowered by a 2D diffusion-based in-painting model, to reconstruct complete surfaces for the hidden parts of objects.
Specifically, we utilize a pre-trained diffusion model to fill in the hidden areas of 2D images. Then we use these in-painted images to optimize a neural implicit surface representation for each instance for 3D reconstruction.
Since creating the in-painting masks needed for this process is tricky, we adopt a human-in-the-loop strategy that involves very little human engagement to generate high-quality masks.
Moreover, some parts of objects can be totally hidden because the videos are usually shot from limited perspectives. To ensure recovering these invisible areas, we develop a cascaded network architecture for predicting signed distance field, making use of different frequency bands of positional encoding and maintaining overall smoothness.
Besides the commonly used rendering loss, Eikonal loss, and silhouette loss, we adopt a CLIP-based semantic consistency loss to guide the surface from unseen camera angles. Experiments on ScanNet scenes show that our proposed framework achieves state-of-the-art accuracy and completeness in object-level reconstruction from scene-level RGB-D videos. Code: https://github.com/THU-LYJ-Lab/O2-Recon.}, number={3}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Hu, Yubin and Ye, Sheng and Zhao, Wang and Lin, Matthieu and He, Yuze and Wen, Yu-Hui and He, Ying and Liu, Yong-Jin}, year={2024}, month={Mar.}, pages={2285-2293} }

@article{Ouyang_Song_Feng_Xu_2024, title={OctOcc: High-Resolution 3D Occupancy Prediction with Octree}, volume={38}, url={https://ojs.aaai.org/index.php/AAAI/article/view/28234}, DOI={10.1609/aaai.v38i5.28234}, abstractNote={3D semantic occupancy has garnered considerable attention due to its abundant structural information encompassing the entire scene in autonomous driving.
However, existing 3D occupancy prediction methods contend with the constraint of low-resolution 3D voxel features arising from the limitation of computational memory.
To address this limitation and achieve a more fine-grained representation of 3D scenes, we propose OctOcc, a novel octree-based approach for 3D semantic occupancy prediction. OctOcc is conceptually rooted in the observation that the vast majority of 3D space is left unoccupied. Capitalizing on this insight, we endeavor to cultivate memory-efficient high-resolution 3D occupancy predictions by mitigating superfluous cross-attentions. Specifically, we devise a hierarchical octree structure that selectively generates finer-grained cross-attentions solely in potentially occupied regions.
Extending our inquiry beyond 3D space, we identify analogous redundancies within another side of cross attentions, 2D images.
Consequently, a 2D image feature filtering network is conceived to expunge extraneous regions.
Experimental results demonstrate that the proposed OctOcc significantly outperforms existing methods on nuScenes and SemanticKITTI datasets with limited memory consumption.}, number={5}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Ouyang, Wenzhe and Song, Xiaolin and Feng, Bailan and Xu, Zenglin}, year={2024}, month={Mar.}, pages={4369-4377} }

@article{Beutner_Finkbeiner_2024, title={On Alternating-Time Temporal Logic, Hyperproperties, and Strategy Sharing}, volume={38}, url={https://ojs.aaai.org/index.php/AAAI/article/view/29679}, DOI={10.1609/aaai.v38i16.29679}, abstractNote={Alternating-time temporal logic (ATL*) is a well-established framework for formal reasoning about multi-agent systems. However, while ATL* can reason about the strategic ability of agents (e.g., some coalition A can ensure that a goal is reached eventually), we cannot compare multiple strategic interactions, nor can we require multiple agents to follow the same strategy. For example, we cannot state that coalition A can reach a goal sooner (or more often) than some other coalition A’. In this paper, we propose HyperATL*_S, an extension of ATL* in which we can (1) compare the outcome of multiple strategic interactions w.r.t. a hyperproperty, i.e., a property that refers to multiple paths at the same time, and (2) enforce that some agents share the same strategy.
We show that HyperATL*_S is a rich specification language that captures important AI-related properties that were out of reach of existing logics. We prove that model checking of HyperATL*_S on concurrent game structures is decidable.
We implement our model-checking algorithm in a tool we call HyMASMC and evaluate it on a range of benchmarks.}, number={16}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Beutner, Raven and Finkbeiner, Bernd}, year={2024}, month={Mar.}, pages={17317-17326} }

@article{Yang_Yin_Liu_Fan_Chen_Yu_Chen_2024, title={PM-INR: Prior-Rich Multi-Modal Implicit Large-Scale Scene Neural Representation}, volume={38}, url={https://ojs.aaai.org/index.php/AAAI/article/view/28481}, DOI={10.1609/aaai.v38i7.28481}, abstractNote={Recent advancements in implicit neural representations have contributed to high-fidelity surface reconstruction and photorealistic novel view synthesis. However, with the expansion of the scene scale, such as block or city level, existing methods
will encounter challenges because traditional sampling cannot cope with the cubically growing sampling space. To alleviate the dependence on filling the sampling space, we explore using multi-modal priors to assist individual points to
obtain more global semantic information and propose a priorrich multi-modal implicit neural representation network, Pm-INR, for the outdoor unbounded large-scale scene. The core of our method is multi-modal prior extraction and crossmodal prior fusion modules. The former encodes codebooks from different modality inputs and extracts valuable priors, while the latter fuses priors to maintain view consistency and preserve unique features among multi-modal priors. Finally, feature-rich cross-modal priors are injected into the sampling
regions to allow each region to perceive global information without filling the sampling space. Extensive experiments have demonstrated the effectiveness and robustness of our method for outdoor unbounded large-scale scene novel
view synthesis, which outperforms state-of-the-art methods in terms of PSNR, SSIM, and LPIPS.}, number={7}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Yang, Yiying and Yin, Fukun and Liu, Wen and Fan, Jiayuan and Chen, Xin and Yu, Gang and Chen, Tao}, year={2024}, month={Mar.}, pages={6594-6602} }

@article{Wu_Su_Li_Wang_2024, title={Pairwise-Label-Based Deep Incremental Hashing with Simultaneous Code Expansion}, volume={38}, url={https://ojs.aaai.org/index.php/AAAI/article/view/28768}, DOI={10.1609/aaai.v38i8.28768}, abstractNote={Deep incremental hashing has become a subject of considerable interest due to its capability to learn hash codes in an incremental manner, eliminating the need to generate codes for classes that have already been learned. However, accommodating more classes requires longer hash codes, and regenerating database codes becomes inevitable when code expansion is required.
In this paper, we present a unified deep hash framework that can simultaneously learn new classes and increase hash code capacity. Specifically, we design a triple-channel asymmetric framework to optimize a new CNN model with a target code length and a code projection matrix. This enables us to directly generate hash codes for new images, and efficiently generate expanded hash codes for original database images from the old ones with the learned projection matrix.
Meanwhile, we propose a pairwise-label-based incremental similarity-preserving loss to optimize the new CNN model, which can incrementally preserve new similarities while maintaining the old ones. Additionally, we design a double-end quantization loss to reduce the quantization error from new and original query images. As a result, our method efficiently embeds both new and original similarities into the expanded hash codes, while keeping the original database codes unchanged.
We conduct extensive experiments on three widely-used image retrieval benchmarks, demonstrating that our method can significantly reduce the time required to expand existing database codes, while maintaining state-of-the-art retrieval performance.}, number={8}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Wu, Dayan and Su, Qinghang and Li, Bo and Wang, Weiping}, year={2024}, month={Mar.}, pages={9169-9177} }

@article{Li_Ji_Wu_Li_Qin_Wei_Zimmermann_2024, title={Panoptic Scene Graph Generation with Semantics-Prototype Learning}, volume={38}, url={https://ojs.aaai.org/index.php/AAAI/article/view/28098}, DOI={10.1609/aaai.v38i4.28098}, abstractNote={Panoptic Scene Graph Generation (PSG) parses objects and predicts their relationships (predicate) to connect human language and visual scenes.
However, different language preferences of annotators and semantic overlaps between predicates lead to biased predicate annotations in the dataset, i.e. different predicates for the same object pairs.
Biased predicate annotations make PSG models struggle in constructing a clear decision plane among predicates, which greatly hinders the real application of PSG models.
To address the intrinsic bias above, we propose a novel framework named ADTrans to adaptively transfer biased predicate annotations to informative and unified ones. To promise consistency and accuracy during the transfer process, we propose to observe the invariance degree of representations in each predicate class, and learn unbiased prototypes of predicates with different intensities. Meanwhile, we continuously measure the distribution changes between each presentation and its prototype, and constantly screen potentially biased data. Finally, with the unbiased predicate-prototype representation embedding space, biased annotations are easily identified.
Experiments show that ADTrans significantly improves the performance of benchmark models, achieving a new state-of-the-art performance, and shows great generalization and effectiveness on multiple datasets. Our code is released at https://github.com/lili0415/PSG-biased-annotation.}, number={4}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Li, Li and Ji, Wei and Wu, Yiming and Li, Mengze and Qin, You and Wei, Lina and Zimmermann, Roger}, year={2024}, month={Mar.}, pages={3145-3153} }

@article{Liu_Li_Fang_Liu_You_Lu_2024, title={Primitive-Based 3D Human-Object Interaction Modelling and Programming}, volume={38}, url={https://ojs.aaai.org/index.php/AAAI/article/view/28161}, DOI={10.1609/aaai.v38i4.28161}, abstractNote={Embedding Human and Articulated Object Interaction (HAOI) in 3D is an important direction for a deeper human activity understanding. Different from previous works that use parametric and CAD models to represent humans and objects, in this work, we propose a novel 3D geometric primitive-based language to encode both humans and objects. Given our new paradigm, humans and objects are all compositions of primitives instead of heterogeneous entities. Thus, mutual information learning may be achieved between the limited 3D data of humans and different object categories. Moreover, considering the simplicity of the expression and the richness of the information it contains, we choose the superquadric as the primitive representation.
To explore an effective embedding of HAOI for the machine, we build a new benchmark on 3D HAOI consisting of primitives together with their images and propose a task requiring machines to recover 3D HAOI using primitives from images.
Moreover, we propose a baseline of single-view 3D reconstruction on HAOI. We believe this primitive-based 3D HAOI representation would pave the way for 3D HAOI studies. Our code and data are available at https://mvig-rhos.com/p3haoi.}, number={4}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Liu, Siqi and Li, Yong-Lu and Fang, Zhou and Liu, Xinpeng and You, Yang and Lu, Cewu}, year={2024}, month={Mar.}, pages={3711-3719} }

@article{Yao_Lu_Zhang_Zhang_Zhao_Yu_2024, title={Progressively Knowledge Distillation via Re-parameterizing Diffusion Reverse Process}, volume={38}, url={https://ojs.aaai.org/index.php/AAAI/article/view/29579}, DOI={10.1609/aaai.v38i15.29579}, abstractNote={Knowledge distillation aims at transferring knowledge from the teacher model to the student one by aligning their distributions. Feature-level distillation often uses L2 distance or its variants as the loss function, based on the assumption that outputs follow normal distributions. This poses a significant challenge when distribution gaps are substantial since this loss function ignores the variance term. To address the problem, we propose to decompose the transfer objective into small parts and optimize it progressively. This process is inspired by diffusion models from which the noise distribution is mapped to the target distribution step by step.
However, directly employing diffusion models is impractical in the distillation scenario due to its heavy reverse process.
To overcome this challenge, we adopt the structural re-parameterization technique to generate multiple student features to approximate the teacher features sequentially. The multiple student features are combined linearly in inference time without extra cost.
We present extensive experiments performed on various transfer scenarios, such as CNN-to-CNN and Transformer-to-CNN, that validate the effectiveness of our approach.}, number={15}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Yao, Xufeng and Lu, Fanbin and Zhang, Yuechen and Zhang, Xinyun and Zhao, Wenqian and Yu, Bei}, year={2024}, month={Mar.}, pages={16425-16432} }

@article{Hammond_Fox_Everitt_Carey_Abate_Wooldridge_2024, title={Reasoning about Causality in Games (Abstract Reprint)}, volume={38}, url={https://ojs.aaai.org/index.php/AAAI/article/view/30597}, DOI={10.1609/aaai.v38i20.30597}, abstractNote={Causal reasoning and game-theoretic reasoning are fundamental topics in artificial intelligence, among many other disciplines: this paper is concerned with their intersection. Despite their importance, a formal framework that supports both these forms of reasoning has, until now, been lacking. We offer a solution in the form of (structural) causal games, which can be seen as extending Pearl’s causal hierarchy to the game-theoretic domain, or as extending Koller and Milch’s multi-agent influence diagrams to the causal domain. We then consider three key questions:
i)
How can the (causal) dependencies in games – either between variables, or between strategies – be modelled in a uniform, principled manner? ii)
How may causal queries be computed in causal games, and what assumptions does this require? iii)
How do causal games compare to existing formalisms? To address question i), we introduce mechanised games, which encode dependencies between agents’ decision rules and the distributions governing the game. In response to question ii), we present definitions of predictions, interventions, and counterfactuals, and discuss the assumptions required for each. Regarding question iii), we describe correspondences between causal games and other formalisms, and explain how causal games can be used to answer queries that other causal or game-theoretic models do not support. Finally, we highlight possible applications of causal games, aided by an extensive open-source Python library.}, number={20}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Hammond, Lewis and Fox, James and Everitt, Tom and Carey, Ryan and Abate, Alessandro and Wooldridge, Michael}, year={2024}, month={Mar.}, pages={22697-22697} }

@article{Yan_Zhang_Guo_Chen_Zhang_Li_Qiao_Dong_He_Gao_2024, title={Referred by Multi-Modality: A Unified Temporal Transformer for Video Object Segmentation}, volume={38}, url={https://ojs.aaai.org/index.php/AAAI/article/view/28465}, DOI={10.1609/aaai.v38i6.28465}, abstractNote={Recently, video object segmentation (VOS) referred by multi-modal signals, e.g., language and audio, has evoked increasing attention in both industry and academia. It is challenging for exploring the semantic alignment within modalities and the visual correspondence across frames.
However, existing methods adopt separate network architectures for different modalities, and neglect the inter-frame temporal interaction with references. In this paper, we propose MUTR, a Multi-modal Unified Temporal transformer for Referring video object segmentation. With a unified framework for the first time, MUTR adopts a DETR-style transformer and is capable of segmenting video objects designated by either text or audio reference. Specifically, we introduce two strategies to fully explore the temporal relations between videos and multi-modal signals. Firstly, for low-level temporal aggregation before the transformer, we enable the multi-modal references to capture multi-scale visual cues from consecutive video frames. This effectively endows the text or audio signals with temporal knowledge and boosts the semantic alignment between modalities.
Secondly, for high-level temporal interaction after the transformer, we conduct inter-frame feature communication for different object embeddings, contributing to better object-wise correspondence for tracking along the video.
On Ref-YouTube-VOS and AVSBench datasets with respective text and audio references, MUTR achieves +4.2% and +8.7% J&amp;F improvements to state-of-the-art methods, demonstrating our significance for unified multi-modal VOS. Code is released at https://github.com/OpenGVLab/MUTR.}, number={6}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Yan, Shilin and Zhang, Renrui and Guo, Ziyu and Chen, Wenchao and Zhang, Wei and Li, Hongyang and Qiao, Yu and Dong, Hao and He, Zhongjiang and Gao, Peng}, year={2024}, month={Mar.}, pages={6449-6457} }

@article{Huang_Wang_Gao_Song_Su_2024, title={Response Enhanced Semi-supervised Dialogue Query Generation}, volume={38}, url={https://ojs.aaai.org/index.php/AAAI/article/view/29790}, DOI={10.1609/aaai.v38i16.29790}, abstractNote={Leveraging vast and continually updated knowledge from the Internet has been considered an important ability for a dialogue system. Therefore, the dialogue query generation task is proposed for generating search queries from dialogue histories, which will be submitted to a search engine for retrieving relevant websites on the Internet. In this regard, previous efforts were devoted to collecting conversations with annotated queries and training a query producer (QP) via standard supervised learning. However, these studies still face the challenges of data scarcity and domain adaptation.
To address these issues, in this paper, we propose a semi-supervised learning framework -- SemiDQG, to improve model performance with unlabeled conversations. Based on the observation that the search query is typically related to the topic of dialogue response, we train a response-augmented query producer (RA) to provide rich and effective training signals for QP.
We first apply a similarity-based query selection strategy to select high-quality RA-generated pseudo queries, which are used to construct pseudo instances for training QP and RA.
Then, we adopt the REINFORCE algorithm to further enhance QP, with RA-provided rewards as fine-grained training signals. Experimental results and in-depth analysis of three benchmarks show the effectiveness of our framework in cross-domain and low-resource scenarios. Particularly, SemiDQG significantly surpasses ChatGPT and competitive baselines. Our code is available at \url{https://github.com/DeepLearnXMU/SemiDQG}.}, number={16}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Huang, Jianheng and Wang, Ante and Gao, Linfeng and Song, Linfeng and Su, Jinsong}, year={2024}, month={Mar.}, pages={18307-18315} }

@article{Mitra_Miroyan_Jain_Kumud_Ranade_Norouzi_2024, title={RetLLM-E: Retrieval-Prompt Strategy for Question-Answering on Student Discussion Forums}, volume={38}, url={https://ojs.aaai.org/index.php/AAAI/article/view/30368}, DOI={10.1609/aaai.v38i21.30368}, abstractNote={This paper focuses on using Large Language Models to support teaching assistants in answering questions on large student forums such as Piazza and EdSTEM. Since student questions on these forums are often closely tied to specific aspects of the institution, instructor, and course delivery, general-purpose LLMs do not directly do well on this task.
We introduce RetLLM-E, a method that combines text-retrieval and prompting approaches to enable LLMs to provide precise and high-quality answers to student questions. When presented with a student question, our system initiates a two-step process. First, it retrieves relevant context from (i) a dataset of student questions addressed by course instructors
(Q&amp;A Retrieval) and (ii) relevant segments of course materials (Document Retrieval). RetLLM-E then prompts LLM using the retrieved text and an engineered prompt structure to
yield an answer optimized for the student question.
We present a set of quantitative and human evaluation experiments, comparing our method to ground truth answers to questions in a test set of actual student questions. Our results demonstrate that our approach provides higher-quality responses to course-related questions than an LLM operating without context or relying solely on retrieval-based context. RetLLM-E can easily be adopted in different courses, providing instructors and students with context-aware automatic responses.}, number={21}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Mitra, Chancharik and Miroyan, Mihran and Jain, Rishi and Kumud, Vedant and Ranade, Gireeja and Norouzi, Narges}, year={2024}, month={Mar.}, pages={23215-23223} }

@article{Li_Zhao_Du_Wang_2024, title={Revisiting the Information Capacity of Neural Network Watermarks: Upper Bound Estimation and Beyond}, volume={38}, url={https://ojs.aaai.org/index.php/AAAI/article/view/30128}, DOI={10.1609/aaai.v38i19.30128}, abstractNote={To trace the copyright of deep neural networks, an owner can embed its identity information into its model as a watermark.
The capacity of the watermark quantify the maximal volume of information that can be verified from the watermarked model.
Current studies on capacity focus on the ownership verification accuracy under ordinary removal attacks and fail to capture the relationship between robustness and fidelity.
This paper studies the capacity of deep neural network watermarks from an information theoretical perspective.
We propose a new definition of deep neural network watermark capacity analogous to channel capacity, analyze its properties, and design an algorithm that yields a tight estimation of its upper bound under adversarial overwriting.
We also propose a universal non-invasive method to secure the transmission of the identity message beyond capacity by multiple rounds of ownership verification. Our observations provide evidence for neural network owners and defenders that are curious about the tradeoff between the integrity of their ownership and the performance degradation of their products.}, number={19}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Li, Fangqi and Zhao, Haodong and Du, Wei and Wang, Shilin}, year={2024}, month={Mar.}, pages={21331-21339} }

@article{Huang_Wu_2024, title={Robustly Improving Bandit Algorithms with Confounded and Selection Biased Offline Data: A Causal Approach}, volume={38}, url={https://ojs.aaai.org/index.php/AAAI/article/view/30027}, DOI={10.1609/aaai.v38i18.30027}, abstractNote={This paper studies bandit problems where an agent has access to offline data that might be utilized to potentially improve the estimation of each arm’s reward distribution. A major obstacle in this setting is the existence of compound biases from the observational data. Ignoring these biases and blindly fitting a model with the biased data could even negatively affect the online learning phase. In this work, we formulate this problem from a causal perspective. First, we categorize the biases into confounding bias and selection bias based on the causal structure they imply. Next, we extract the causal bound for each arm that is robust towards compound biases from biased observational data. The derived bounds contain the
ground truth mean reward and can effectively guide the bandit agent to learn a nearly-optimal decision policy. We also conduct regret analysis in both contextual and non-contextual bandit settings and show that prior causal bounds could help
consistently reduce the asymptotic regret.}, number={18}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Huang, Wen and Wu, Xintao}, year={2024}, month={Mar.}, pages={20438-20446} }

@article{Wang_Wang_Chen_Zhao_2024, title={STAIR: Spatial-Temporal Reasoning with Auditable Intermediate Results for Video Question Answering}, volume={38}, url={https://ojs.aaai.org/index.php/AAAI/article/view/29890}, DOI={10.1609/aaai.v38i17.29890}, abstractNote={Recently we have witnessed the rapid development of video question answering models. However, most models can only handle simple videos in terms of temporal reasoning, and their performance tends to drop when answering temporal-reasoning questions on long and informative videos. To tackle this problem we propose STAIR, a Spatial-Temporal Reasoning model with Auditable Intermediate Results for video question answering. STAIR is a neural module network, which contains a program generator to decompose a given question into a hierarchical combination of several sub-tasks, and a set of lightweight neural modules to complete each of these sub-tasks.
Though neural module networks are already widely studied on image-text tasks, applying them to videos is a non-trivial task, as reasoning on videos requires different abilities. In this paper, we define a set of basic video-text sub-tasks for video question answering and design a set of lightweight modules to complete them.
Different from most prior works, modules of STAIR return intermediate outputs specific to their intentions instead of always returning attention maps, which makes it easier to interpret and collaborate with pre-trained models. We also introduce intermediate supervision to make these intermediate outputs more accurate. We conduct extensive experiments on several video question answering datasets under various settings to show STAIR’s performance, explainability, compatibility with pre-trained models, and applicability when program annotations are not available. Code: https://github.com/yellow-binary-tree/STAIR}, number={17}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Wang, Yueqian and Wang, Yuxuan and Chen, Kai and Zhao, Dongyan}, year={2024}, month={Mar.}, pages={19215-19223} }

@article{Wang_Yin_NS_Drgoňa_Schram_Halappanavar_Liu_Li_2024, title={Semi-supervised Learning of Dynamical Systems with Neural Ordinary Differential Equations: A Teacher-Student Model Approach}, volume={38}, url={https://ojs.aaai.org/index.php/AAAI/article/view/29498}, DOI={10.1609/aaai.v38i14.29498}, abstractNote={Modeling dynamical systems is crucial for a wide range of tasks, but it remains challenging due to complex nonlinear dynamics, limited observations, or lack of prior knowledge. Recently, data-driven approaches such as Neural Ordinary Differential Equations (NODE) have shown promising results by leveraging the expressive power of neural networks to model unknown dynamics. However, these approaches often suffer from limited labeled training data, leading to poor generalization and suboptimal predictions. On the other hand, semi-supervised algorithms can utilize abundant unlabeled data and have demonstrated good performance in classification and regression tasks.
We propose TS-NODE, the first semi-supervised approach to modeling dynamical systems with NODE. TS-NODE explores cheaply generated synthetic pseudo rollouts to broaden exploration in the state space and to tackle the challenges brought by lack of ground-truth system data under a teacher-student model. TS-NODE employs an unified optimization framework that corrects the teacher model based on the student’s feedback while mitigating the potential false system dynamics present in pseudo rollouts.
TS-NODE demonstrates significant performance improvements over a baseline Neural ODE model on multiple dynamical system modeling tasks.}, number={14}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Wang, Yu and Yin, Yuxuan and NS, Karthik Somayaji and Drgoňa, Ján and Schram, Malachi and Halappanavar, Mahantesh and Liu, Frank and Li, Peng}, year={2024}, month={Mar.}, pages={15698-15705} }

@article{Hu_Cavicchioli_Berardinelli_Capotondi_2024, title={ShareBERT: Embeddings Are Capable of Learning Hidden Layers}, volume={38}, url={https://ojs.aaai.org/index.php/AAAI/article/view/29781}, DOI={10.1609/aaai.v38i16.29781}, abstractNote={The deployment of Pre-trained Language Models in memory-limited devices is hindered by their massive number of parameters, which motivated the interest in developing smaller architectures.
Established works in the model compression literature showcased that small models often present a noticeable performance degradation and need to be paired with transfer learning methods, such as Knowledge Distillation. In this work, we propose a parameter-sharing method that consists of sharing parameters between embeddings and the hidden layers, enabling the design of near-zero parameter encoders. To demonstrate its effectiveness, we present an architecture design called ShareBERT, which can preserve up to 95.5%
of BERT Base performances, using only 5M parameters (21.9× fewer parameters) without the help of Knowledge Distillation. We demonstrate empirically that our proposal does not negatively affect the model learning capabilities and that it is even beneficial for representation learning. Code will be available at https://github.com/jchenghu/sharebert.}, number={16}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Hu, Jia Cheng and Cavicchioli, Roberto and Berardinelli, Giulia and Capotondi, Alessandro}, year={2024}, month={Mar.}, pages={18225-18233} }

@article{Wu_Chi_Zang_Peng_2024, title={Solving Spectrum Unmixing as a Multi-Task Bayesian Inverse Problem with Latent Factors for Endmember Variability}, volume={38}, url={https://ojs.aaai.org/index.php/AAAI/article/view/29518}, DOI={10.1609/aaai.v38i14.29518}, abstractNote={With the increasing customization of spectrometers, spectral unmixing has become a widely used technique in fields such as remote sensing, textiles, and environmental protection.
However, endmember variability is a common issue for unmixing, where changes in lighting, atmospheric, temporal conditions, or the intrinsic spectral characteristics of materials, can all result in variations in the measured spectrum.
Recent studies have employed deep neural networks to tackle endmember variability. However, these approaches rely on generic networks to implicitly resolve the issue, which struggles with the ill-posed nature and lack of effective convergence constraints for endmember variability. This paper proposes a streamlined multi-task learning model to rectify this problem, incorporating abundance regression and multi-label classification with Unmixing as a Bayesian Inverse Problem, denoted as BIPU. To address the issue of the ill-posed nature, the uncertainty of unmixing is quantified and minimized through the Laplace approximation in a Bayesian inverse solver. In addition, to improve convergence under the influence of endmember variability, the paper introduces two types of constraints. The first separates background factors of variants from the initial factors for each endmember, while the second identifies and eliminates the influence of non-existent endmembers via multi-label classification during convergence.
The effectiveness of this model is demonstrated not only on a self-collected near-infrared spectral textile dataset (FENIR), but also on three commonly used remote sensing hyperspectral image datasets, where it achieves state-of-the-art unmixing performance and exhibits strong generalization capabilities.}, number={14}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Wu, Dong and Chi, Mingmin and Zang, Xuan and Peng, Bo}, year={2024}, month={Mar.}, pages={15878-15887} }

@article{Xu_Xu_Wang_Xu_Guo_Zhang_Zhang_2024, title={Spectral Prompt Tuning: Unveiling Unseen Classes for Zero-Shot Semantic Segmentation}, volume={38}, url={https://ojs.aaai.org/index.php/AAAI/article/view/28456}, DOI={10.1609/aaai.v38i6.28456}, abstractNote={Recently, CLIP has found practical utility in the domain of pixel-level zero-shot segmentation tasks. The present landscape features two-stage methodologies beset by issues such as intricate pipelines and elevated computational costs. While current one-stage approaches alleviate these concerns and incorporate Visual Prompt Training (VPT) to uphold CLIP’s generalization capacity, they still fall short in fully harnessing CLIP’s potential for pixel-level unseen class demarcation and precise pixel predictions.
To further stimulate CLIP’s zero-shot dense prediction capability, we propose SPT-SEG, a one-stage approach that improves CLIP’s adaptability from image to pixel.
Specifically, we initially introduce Spectral Prompt Tuning (SPT), incorporating spectral prompts into the CLIP visual encoder’s shallow layers to capture structural intricacies of images, thereby enhancing comprehension of unseen classes.
Subsequently, we introduce the Spectral Guided Decoder (SGD), utilizing both high and low-frequency information to steer the network’s spatial focus towards more prominent classification features, enabling precise pixel-level prediction outcomes.
Through extensive experiments on two public datasets, we demonstrate the superiority of our method over state-of-the-art approaches, performing well across all classes and particularly excelling in handling unseen classes.}, number={6}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Xu, Wenhao and Xu, Rongtao and Wang, Changwei and Xu, Shibiao and Guo, Li and Zhang, Man and Zhang, Xiaopeng}, year={2024}, month={Mar.}, pages={6369-6377} }

@article{Ren_Lu_Ying_Rotskoff_2024, title={Statistical Spatially Inhomogeneous Diffusion Inference}, volume={38}, url={https://ojs.aaai.org/index.php/AAAI/article/view/29401}, DOI={10.1609/aaai.v38i13.29401}, abstractNote={Inferring a diffusion equation from discretely observed measurements is a statistical challenge of significant importance in a variety of fields, from single-molecule tracking in biophysical systems to modeling financial instruments.
Assuming that the underlying dynamical process obeys a d-dimensional stochastic differential equation of the form dx_t = b(x_t)dt + \Sigma(x_t)dw_t, we propose neural network-based estimators of both the drift b and the spatially-inhomogeneous diffusion tensor D = \Sigma\Sigma^T/2 and provide statistical convergence guarantees when b and D are s-Hölder continuous. Notably, our bound aligns with the minimax optimal rate N^{-\frac{2s}{2s+d } for nonparametric function estimation even in the presence of correlation within observational data, which necessitates careful handling when establishing fast-rate generalization bounds.
Our theoretical results are bolstered by numerical experiments demonstrating accurate inference of spatially-inhomogeneous diffusion tensors.}, number={13}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Ren, Yinuo and Lu, Yiping and Ying, Lexing and Rotskoff, Grant M.}, year={2024}, month={Mar.}, pages={14820-14828} }

@article{Chen_Yuan_Liu_Liu_Guan_Guo_Peng_Liu_Li_Xiao_2024, title={Talk Funny! A Large-Scale Humor Response Dataset with Chain-of-Humor Interpretation}, volume={38}, url={https://ojs.aaai.org/index.php/AAAI/article/view/29736}, DOI={10.1609/aaai.v38i16.29736}, abstractNote={Humor is a crucial part of human communication. Understanding humor and generating humorous responses in dialogue can provide natural and empathic human-computer interactions.
However, most existing pre-trained language models (PLMs) perform unsatisfactorily in humor generation.
On one hand, the serious shortage of humor corpus and datasets pose challenges for constructing models that can understand and generate humorous expressions. On the other hand, humor generation relies on rich knowledge and commonsense, which is often tacit and unspoken.
In this paper, we construct the largest Chinese Explainable Humor Response Dataset to date with chain-of-humor and humor mind map annotations, which can be used to comprehensively evaluate as well as improve the humorous response ability of PLMs.
We further design humor-related auxiliary tasks to further enhance PLMs’ humorous response performance.
Extensive evaluations demonstrate that our proposed dataset and auxiliary tasks effectively help PLMs to generate humorous responses, laying the groundwork for future humor research.}, number={16}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Chen, Yuyan and Yuan, Yichen and Liu, Panjun and Liu, Dayiheng and Guan, Qinghao and Guo, Mengfei and Peng, Haiming and Liu, Bang and Li, Zhixu and Xiao, Yanghua}, year={2024}, month={Mar.}, pages={17826-17834} }

@article{Zeng_Meng_Yin_Zhou_2024, title={Teaching Large Language Models to Translate with Comparison}, volume={38}, url={https://ojs.aaai.org/index.php/AAAI/article/view/29920}, DOI={10.1609/aaai.v38i17.29920}, abstractNote={Open-sourced large language models (LLMs) have demonstrated remarkable efficacy in various tasks with instruction tuning. However, these models can sometimes struggle with tasks that require more specialized knowledge such as translation. One possible reason for such deficiency is that instruction tuning aims to generate fluent and coherent text that continues from a given instruction without being constrained by any task-specific requirements. Moreover, it can be more challenging to tune smaller LLMs with lower-quality training data.
To address this issue, we propose a novel framework using examples in comparison to teach LLMs to learn translation. Our approach involves output comparison and preference comparison, presenting the model with carefully designed examples of correct and incorrect translations and an additional preference loss for better regularization.
Empirical evaluation on four language directions of WMT2022 and FLORES-200 benchmarks shows the superiority of our proposed method over existing methods. Our findings offer a new perspective on fine-tuning LLMs for translation tasks and provide a promising solution for generating high-quality translations.
Please refer to Github for more details:
https://github.com/lemon0830/TIM.}, number={17}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Zeng, Jiali and Meng, Fandong and Yin, Yongjing and Zhou, Jie}, year={2024}, month={Mar.}, pages={19488-19496} }

@article{Zhou_Xiong_Wu_2024, title={Test-Time Adaptation via Style and Structure Guidance for Histological Image Registration}, volume={38}, url={https://ojs.aaai.org/index.php/AAAI/article/view/28601}, DOI={10.1609/aaai.v38i7.28601}, abstractNote={Image registration plays a crucial role in histological image analysis, encompassing tasks like multi-modality fusion and disease grading. Traditional registration methods optimize objective functions for each image pair, yielding reliable accuracy but demanding heavy inference burdens.
Recently, learning-based registration methods utilize networks to learn the optimization process during training and apply a one-step forward process during testing. While these methods offer promising registration performance with reduced inference time, they remain sensitive to appearance variances and local structure changes commonly encountered in histological image registration scenarios.
In this paper, for the first time, we propose a novel test-time adaptation method for histological image registration, aiming to improve the generalization ability of learning-based methods. Specifically, we design two operations, style guidance and shape guidance, for the test-time adaptation process. The former leverages style representations encoded by feature statistics to address the issue of appearance variances, while the latter incorporates shape representations encoded by HOG features to improve registration accuracy in regions with structural changes.
Furthermore, we consider the continuity of the model during the test-time adaptation process.
Different from the previous methods initialized by a given trained model, we introduce a smoothing strategy to leverage historical models for better generalization. We conduct experiments with several representative learning-based backbones on the public histological dataset, demonstrating the superior registration performance of our test-time adaptation method.}, number={7}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Zhou, Shenglong and Xiong, Zhiwei and Wu, Feng}, year={2024}, month={Mar.}, pages={7677-7685} }

@article{Yoo_Choi_2024, title={Topic-VQ-VAE: Leveraging Latent Codebooks for Flexible Topic-Guided Document Generation}, volume={38}, url={https://ojs.aaai.org/index.php/AAAI/article/view/29913}, DOI={10.1609/aaai.v38i17.29913}, abstractNote={This paper introduces a novel approach for topic modeling utilizing latent codebooks from Vector-Quantized Variational Auto-Encoder~(VQ-VAE), discretely encapsulating the rich information of the pre-trained embeddings such as the pre-trained language model.
From the novel interpretation of the latent codebooks and embeddings as conceptual bag-of-words, we propose a new generative topic model called Topic-VQ-VAE~(TVQ-VAE) which inversely generates the original documents related to the respective latent codebook.
The TVQ-VAE can visualize the topics with various generative distributions including the traditional BoW distribution and the autoregressive image generation.
Our experimental results on document analysis and image generation demonstrate that TVQ-VAE effectively captures the topic context which reveals the underlying structures of the dataset and supports flexible forms of document generation.
Official implementation of the proposed TVQ-VAE is available at https://github.com/clovaai/TVQ-VAE.}, number={17}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Yoo, YoungJoon and Choi, JongWon}, year={2024}, month={Mar.}, pages={19422-19430} }

@article{Zhang_Yang_Liu_Xu_Rong_Feng_2024, title={Towards a Theoretical Understanding of Why Local Search Works for Clustering with Fair-Center Representation}, volume={38}, url={https://ojs.aaai.org/index.php/AAAI/article/view/29638}, DOI={10.1609/aaai.v38i15.29638}, abstractNote={The representative k-median problem generalizes the classical clustering formulations in that it partitions the data points into several disjoint demographic groups and poses a lower-bound constraint on the number of opened facilities from each group, such that all the groups are fairly represented by the opened facilities. Due to its simplicity, the local-search heuristic that optimizes an initial solution by iteratively swapping at most a constant number of closed facilities for the same number of opened ones (denoted by the O(1)-swap heuristic) has been frequently used in the representative k-median problem. Unfortunately, despite its good performance exhibited in experiments, whether the O(1)-swap heuristic has provable approximation guarantees for the case where the number of groups is more than 2 remains an open question for a long time. As an answer to this question, we show that the O(1)-swap heuristic
(1) is guaranteed to yield a constant-factor approximation solution if the number of groups is a constant, and
(2) has an unbounded approximation ratio otherwise.
Our main technical contribution is a new approach for theoretically analyzing local-search heuristics, which derives the approximation ratio of the O(1)-swap heuristic via linearly combining the increased clustering costs induced by a set of hierarchically organized swaps.}, number={15}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Zhang, Zhen and Yang, Junfeng and Liu, Limei and Xu, Xuesong and Rong, Guozhen and Feng, Qilong}, year={2024}, month={Mar.}, pages={16953-16960} }

@article{An_Tian_Shi_Chen_Wu_Wang_Chen_2024, title={Transfer and Alignment Network for Generalized Category Discovery}, volume={38}, url={https://ojs.aaai.org/index.php/AAAI/article/view/28959}, DOI={10.1609/aaai.v38i10.28959}, abstractNote={Generalized Category Discovery (GCD) is a crucial real-world task that aims to recognize both known and novel categories from an unlabeled dataset by leveraging another labeled dataset with only known categories. Despite the improved performance on known categories, current methods perform poorly on novel categories. We attribute the poor performance to two reasons: biased knowledge transfer between labeled and unlabeled data and noisy representation learning on the unlabeled data. The former leads to unreliable estimation of learning targets for novel categories and the latter hinders models from learning discriminative features. To mitigate these two issues, we propose a Transfer and Alignment Network (TAN), which incorporates two knowledge transfer mechanisms to calibrate the biased knowledge and two feature alignment mechanisms to learn discriminative features.
Specifically, we model different categories with prototypes and transfer the prototypes in labeled data to correct model bias towards known categories. On the one hand, we pull instances with known categories in unlabeled data closer to these prototypes to form more compact clusters and avoid boundary overlap between known and novel categories. On the other hand, we use these prototypes to calibrate noisy prototypes estimated from unlabeled data based on category similarities, which allows for more accurate estimation of prototypes for novel categories that can be used as reliable learning targets later. After knowledge transfer, we further propose two feature alignment mechanisms to acquire both instance- and category-level knowledge from unlabeled data by aligning instance features with both augmented features and the calibrated prototypes, which can boost model performance on both known and novel categories with less noise. Experiments on three benchmark datasets show that our model outperforms SOTA methods, especially on novel categories. Theoretical analysis is provided for an in-depth understanding of our model in general.
Our code and data are available at https://github.com/Lackel/TAN.}, number={10}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={An, Wenbin and Tian, Feng and Shi, Wenkai and Chen, Yan and Wu, Yaqiang and Wang, Qianying and Chen, Ping}, year={2024}, month={Mar.}, pages={10856-10864} }

@article{Rashid_Amparore_Ferrari_Verda_2024, title={Using Stratified Sampling to Improve LIME Image Explanations}, volume={38}, url={https://ojs.aaai.org/index.php/AAAI/article/view/29397}, DOI={10.1609/aaai.v38i13.29397}, abstractNote={We investigate the use of a stratified sampling approach for LIME Image, a popular model-agnostic explainable AI method for computer vision tasks, in order to reduce the artifacts generated by typical Monte Carlo sampling.
Such artifacts are due to the undersampling of the dependent variable in the synthetic neighborhood around the image being explained, which may result in inadequate explanations due to the impossibility of fitting a linear regressor on the sampled data.
We then highlight a connection with the Shapley theory, where similar arguments about undersampling and sample relevance were suggested in the past.
We derive all the formulas and adjustment factors required for an unbiased stratified sampling estimator. Experiments show the efficacy of the proposed approach.}, number={13}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Rashid, Muhammad and Amparore, Elvio G. and Ferrari, Enrico and Verda, Damiano}, year={2024}, month={Mar.}, pages={14785-14792} }

@article{Zou_Gao_Ye_Chen_Yang_Huang_Chen_Chen_2024, title={VQCNIR: Clearer Night Image Restoration with Vector-Quantized Codebook}, volume={38}, url={https://ojs.aaai.org/index.php/AAAI/article/view/28623}, DOI={10.1609/aaai.v38i7.28623}, abstractNote={Night photography often struggles with challenges like low light and blurring, stemming from dark environments and prolonged exposures. Current methods either disregard priors and directly fitting end-to-end networks, leading to inconsistent illumination, or rely on unreliable handcrafted priors to constrain the network, thereby bringing the greater error to the final result. We believe in the strength of data-driven high-quality priors and strive to offer a reliable and consistent prior, circumventing the restrictions of manual priors.
In this paper, we propose Clearer Night Image Restoration with Vector-Quantized Codebook (VQCNIR) to achieve remarkable and consistent restoration outcomes on real-world and synthetic benchmarks. To ensure the faithful restoration of details and illumination, we propose the incorporation of two essential modules: the Adaptive Illumination Enhancement Module (AIEM) and the Deformable Bi-directional Cross-Attention (DBCA) module. The AIEM leverages the inter-channel correlation of features to dynamically maintain illumination consistency between degraded features and high-quality codebook features. Meanwhile, the DBCA module effectively integrates texture and structural information through bi-directional cross-attention and deformable convolution, resulting in enhanced fine-grained detail and structural fidelity across parallel decoders.
Extensive experiments validate the remarkable benefits of VQCNIR in enhancing image quality under low-light conditions, showcasing its state-of-the-art performance on both synthetic and real-world datasets. The code is available at https://github.com/AlexZou14/VQCNIR.}, number={7}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Zou, Wenbin and Gao, Hongxia and Ye, Tian and Chen, Liang and Yang, Weipeng and Huang, Shasha and Chen, Hongsheng and Chen, Sixiang}, year={2024}, month={Mar.}, pages={7873-7881} }

@article{Xu_Gao_Song_Hao_2024, title={Weakly Supervised Multimodal Affordance Grounding for Egocentric Images}, volume={38}, url={https://ojs.aaai.org/index.php/AAAI/article/view/28451}, DOI={10.1609/aaai.v38i6.28451}, abstractNote={To enhance the interaction between intelligent systems and the environment, locating the affordance regions of objects is crucial. These regions correspond to specific areas that provide distinct functionalities. Humans often acquire the ability to identify these regions through action demonstrations and verbal instructions. In this paper, we present a novel multimodal framework that extracts affordance knowledge from exocentric images, which depict human-object interactions, as well as from accompanying textual descriptions that describe the performed actions. The extracted knowledge is then transferred to egocentric images.
To achieve this goal, we propose the HOI-Transfer Module, which utilizes local perception to disentangle individual actions within exocentric images. This module effectively captures localized features and correlations between actions, leading to valuable affordance knowledge. Additionally, we introduce the Pixel-Text Fusion Module, which fuses affordance knowledge by identifying regions in egocentric images that bear resemblances to the textual features defining affordances.
We employ a Weakly Supervised Multimodal Affordance (WSMA) learning approach, utilizing image-level labels for training. Through extensive experiments, we demonstrate the superiority of our proposed method in terms of evaluation metrics and visual results when compared to existing affordance grounding models. Furthermore, ablation experiments confirm the effectiveness of our approach. Code:https://github.com/xulingjing88/WSMA.}, number={6}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Xu, Lingjing and Gao, Yang and Song, Wenfeng and Hao, Aimin}, year={2024}, month={Mar.}, pages={6324-6332} }

@article{Singh_Firdaus_Chauhan_Ekbal_Bhattacharyya_2024, title={Well, Now We Know! Unveiling Sarcasm: Initiating and Exploring Multimodal Conversations with Reasoning}, volume={38}, url={https://ojs.aaai.org/index.php/AAAI/article/view/29864}, DOI={10.1609/aaai.v38i17.29864}, abstractNote={Sarcasm is a widespread linguistic phenomenon that poses a considerable challenge to explain due to its subjective nature, absence of contextual cues, and rooted personal
perspectives. Even though the identification of sarcasm has been extensively studied in dialogue analysis, merely detecting sarcasm falls short of enabling conversational systems to genuinely comprehend the underlying meaning of a conversation and generate fitting responses. It is imperative to not only detect sarcasm but also pinpoint its origination and the rationale behind the sarcastic expressions to capture its authentic essence. In this paper, we delve into the discourse structure of conversations infused with sarcasm and introduce a novel task - Sarcasm Initiation and Reasoning in Conversations (SIRC). Embedded in a multimodal environment and
involving a combination of both English and code-mixed interactions, the objective of the task is to discern the trigger or starting point of sarcasm. Additionally, the task involves producing a natural language explanation that rationalizes the satirical dialogues. To this end, we introduce Sarcasm Initiation and Reasoning Dataset (SIRD) to facilitate our task and provide sarcasm initiation annotations and reasoning. We develop a comprehensive model named Sarcasm Initiation and Reasoning Generation (SIRG), which is designed to encompass textual, audio, and visual representations. To achieve this, we introduce a unique shared fusion method that employs cross-attention mechanisms to seamlessly integrate these diverse modalities. Our experimental outcomes, conducted on the SIRC dataset, demonstrate that our proposed framework establishes a new benchmark for both sarcasm initiation and its reasoning generation in the context of multimodal conversations. The code and dataset can be accessed from https://www.iitp.ac.in/∼ai-nlp-ml resources.html#sarcasm-explain and https://github.com/GussailRaat/SIRG-Sarcasm-Initiation-and-Reasoning-Generation.}, number={17}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Singh, Gopendra Vikram and Firdaus, Mauajama and Chauhan, Dushyant Singh and Ekbal, Asif and Bhattacharyya, Pushpak}, year={2024}, month={Mar.}, pages={18981-18989} }

@article{Wu_Zhang_Xu_Liao_Yao_Yu_2024, title={p-Laplacian Adaptation for Generative Pre-trained Vision-Language Models}, volume={38}, url={https://ojs.aaai.org/index.php/AAAI/article/view/28415}, DOI={10.1609/aaai.v38i6.28415}, abstractNote={Vision-Language models (VLMs) pre-trained on large corpora have demonstrated notable success across a range of downstream tasks. In light of the rapidly increasing size of pre-trained VLMs, parameter-efficient transfer learning (PETL) has garnered attention as a viable alternative to full fine-tuning. One such approach is the adapter, which introduces a few trainable parameters into the pre-trained models while preserving the original parameters during adaptation.
In this paper, we present a novel modeling framework that recasts adapter tuning after attention as a graph message passing process on attention graphs, where the projected query and value features and attention matrix constitute the node features and the graph adjacency matrix, respectively. Within this framework, tuning adapters in VLMs necessitates handling heterophilic graphs, owing to the disparity between the projected query and value space.
To address this challenge, we propose a new adapter architecture, p-adapter, which employs p-Laplacian message passing in Graph Neural Networks (GNNs). Specifically, the attention weights are re-normalized based on the features, and the features are then aggregated using the calibrated attention matrix, enabling the dynamic exploitation of information with varying frequencies in the heterophilic attention graphs.
We conduct extensive experiments on different pre-trained VLMs and multi-modal tasks, including visual question answering, visual entailment, and image captioning. The experimental results validate our method’s significant superiority over other PETL methods. Our code is available at https://github.com/wuhy68/p-Adapter/.}, number={6}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Wu, Haoyuan and Zhang, Xinyun and Xu, Peng and Liao, Peiyu and Yao, Xufeng and Yu, Bei}, year={2024}, month={Mar.}, pages={6003-6011} }
